      "chapterId": "han-shu_ch-1",
      "order": 1,
      "canonicalText": "高祖，沛豐邑中陽里人也，姓劉氏。母媼嘗息大澤之陂，夢與神遇。是時雷電晦冥，父太公往視，則見交龍於上。已而有娠，遂產高祖。",
