      "readingAid": {
        "translation": "漢高祖劉邦，是沛郡豐邑中陽里人，家族姓劉。他的母親劉媼曾經在大澤的堤岸邊小憩歇息，夢見與神靈相遇。這時天空中雷電交加、天昏地暗，父親太公急忙前往探視，只見一條蛟龍盤旋交騰在劉媼身上。不久之後劉媼便懷了身孕，隨後誕生下了漢高祖。",
        "analysis": "【篇旨與高帝紀開篇帝王感生神話政治合法性】班固《漢書・高帝紀》開篇——記載漢高祖劉邦之籍貫家世與「母夢神遇、交龍於上」之感生神異傳奇，確立漢代「受命於天」之君權神授神聖敘事。\\n【詞義訓詁】「大澤之陂」：陂，音波，水澤堤岸；「交龍於上」：古代帝王感龍而生之政治符號；「已而有娠」：娠，懷孕。\\n【史學考釋】班固承襲《史記》敘事，將劉邦平民崛起包裝為天命所歸之必然歷史進程，反映兩漢之際天命讖緯思潮之深遠影響。"
      }
