      "order": 2,
      "canonicalText": "高祖為人，隆準而龍顏，美須髯，左股有七十二黑子。寬仁愛人，意豁如也。常有大度，不事家人生產作業。及壯，為泗水亭長，廷中吏無所不狎侮。好酒及色。常從王媼、武負貰酒，醉臥，武負、王媼見其上常有怪。高祖每酤留飲，酒讎數倍。及見怪，歲年底，此兩家常折券棄責。",
