      "id": "han-shu_ch-1_p-4",
      "chapterId": "han-shu_ch-1",
      "order": 4,
      "canonicalText": "單父人呂公善沛令，避仇從之客，因家沛焉。沛中豪桀吏聞令有客，皆往賀。蕭何為主吏，主進，令諸大夫曰：「進不滿千錢，坐之堂下。」高祖為亭長，素易諸吏，乃誑為謁曰「賀錢萬」，實不持一錢。謁入，呂公大驚，起，迎之門。呂公者，好相人，見高祖狀貌，因奇之，引向上坐。蕭何曰：「劉季固多大言，少成事。」高祖因狎侮諸客，遂坐上坐，無所誶。酒闌，呂公因目固留高祖。高祖罷之後，呂公曰：「臣少好相人，相人多矣，無如季相，願季自愛。臣有息女，願為季箕帚妾。」酒罷，呂媼怒呂公曰：「公始常欲奇此女，與貴人。沛令善公，求之不與，何自妄許劉季？」呂公曰：「此非兒女子所知也。」卒與高祖。呂公女乃呂後也，生孝惠帝、魯元公主。",
