      "readingAid": {
        "translation": "單父縣人呂公與沛縣縣令交情甚篤，為了躲避仇家前來投奔縣令做客，於是舉家定居在沛縣。沛縣城中的各界豪傑士紳與官吏聽聞縣令家來了貴客，紛紛前往宴席祝賀。主吏蕭何負責主管登記賀禮錢財（主進），向全體來賓宣佈規定說：進獻賀錢不滿一千錢的賓客，一律安排坐在廳堂之下。高祖當時身為亭長，平素就看輕縣衙各級官吏，於是在名帖上虛報欺騙寫道賀錢一萬，實際上連一文錢都沒帶。名帖遞進去後，呂公大為震驚，親自起身離席快步走到大門口熱情迎接。呂公平生極其擅長相面識人，看見高祖相貌魁偉神異，便感到無比驚奇，恭敬地引導他登上廳堂正座入席。蕭何私下提醒呂公說：劉季（劉邦）平時就慣常愛說大話，很少辦成過實事。高祖在席間隨意談笑調侃戲弄滿堂賓客，坦然端坐在首席正座之上，毫無任何愧怍拘束。酒宴即將結束之際，呂公頻頻用眼神示意高祖，執意將他單獨挽留下來。等到其他賓客全部散去之後，呂公對高祖說：我自幼喜愛替人相面，相過的面相太多了，但從未見過有哪個人的面相能比得上您劉季這般尊貴神異，希望您日後好自珍愛！我有個親生女兒（呂雉），願意嫁給您充當操持家務的結髮妻子（箕帚妾）。宴會結束後，呂公的妻子呂媼憤怒地責怪呂公說：你當初常常自誇想把這個女兒奇貨可居嫁給大富大貴之人！沛縣縣令同你交情那麼好，親自前來求婚你都不肯答應，如今為什麼自作主張胡亂許配給那個一無所有的劉季？呂公回答說：這其中的深奧天機，非你們婦道人家所能懂得的！最終堅決將女兒嫁給了高祖。呂公的這個女兒就是日後的呂後，她為高祖生下了漢惠帝劉盈與魯元公主。",
        "analysis": "【篇旨與賀錢萬不持一錢呂公相面許配呂後】千古經典名場面——劉邦不持一錢誑稱「賀錢萬」傲視滿堂豪傑，呂公以相人之術識拔潛龍，堅決將呂雉下嫁劉邦，奠定漢帝國開國後族之深厚聯盟。\\n【詞義訓詁】「素易諸吏」：易，輕慢看輕；「誑為謁」：名帖上虛報謊稱；「箕帚妾」：謙稱操持家務之結髮妻子；「折券棄責」：展現其與基層各階層的特殊互信。\\n【政治聯姻考釋】呂氏家族在單父與沛縣皆具資財名望，此番聯姻為劉邦日後起義提供了強大的財政宗族支持與政治班底。"
      }
