      "chapterId": "han-shu_ch-1",
      "order": 6,
      "canonicalText": "高祖以亭長為縣送徒酈山，徒多道亡。自度比至皆亡之，到豐西澤中，止飲，夜皆解縱所送徒。曰：「公等皆去，吾亦從此逝矣！」徒中壯士願從者十餘人。",
