      "chapterId": "han-shu_ch-1",
      "order": 7,
      "canonicalText": "高祖被酒，夜徑澤中，令一人行前。行前果還，報曰：「前有大蛇當徑，願還。」高祖醉，曰：「壯士行，何畏！」乃前，拔劍擊斬蛇。蛇遂分為兩，徑開。行數裏，醉，因臥。後人來至蛇所，有一老媼夜哭。人問何哭，媼曰：「人殺吾子，故哭之。」人曰：「媼子何為見殺？」媼曰：「吾子，白帝子也，化為蛇，當道，今者赤帝子斬之，故哭。」人乃以媼為不誠，欲告之，媼因忽不見。後人至，高祖覺。告高祖，高祖乃心獨喜，自負。諸從者日益畏之。",
