      "readingAid": {
        "translation": "高祖帶著幾分醉意，深夜抄小路穿行在豐西大澤之中，派遣一名壯士在前面探路。探路的人忽然折返回來報告說：前方有一條巨大的巨蛇擋住了去路，希望您折返回去。高祖醉意朦朧地豪邁說道：大丈夫豪傑趕路，有什麼好害怕畏懼的！於是快步走上前去，拔出佩劍奮力揮砍斬殺巨蛇。巨蛇當場被斬斷劈為兩段，道路頓時暢通無阻。高祖又向前行走了數里路，因醉酒難耐，便倒在路旁草叢中呼呼大睡。後面跟隨的人走到剛才斬蛇的地點時，看見有一個老婦人在深夜對著蛇屍痛哭流涕。路人詢問她為什麼哭泣，老婦人回答說：有人殺害了我的親生兒子，所以我纔在這裡痛哭啊！路人問：您的兒子為什麼會被殺害呢？老婦人回答說：我的兒子乃是白帝之子，化身為巨蛇擋在大道中央，如今被剛才路過的赤帝之子拔劍斬殺了，所以我纔在此悲傷痛哭！路人以為老婦人在胡言亂語編造謊言，正打算上前責備訓斥她，老婦人卻忽然化作一陣青煙憑空消失不見了！後面的人追上高祖時，高祖剛剛酒醒。眾人把剛才遇見老婦人的奇事一五一十告訴了高祖，高祖內心暗自無比驚喜，更加自信自負。所有跟隨他的壯士對他日益敬畏服從。",
        "analysis": "【篇旨與芒碭斬蛇赤帝子斬白帝子漢興五德終始符應】漢帝國最核心的神聖合法性神話——高祖酒醉夜斬白蛇，老媼夜哭「赤帝子斬白帝子」，以五行五德終始說將秦朝（白帝/金德）的覆滅與漢朝（赤帝/火德）的興起賦予天命神聖性。\\n【詞義訓詁】「被酒」：被，音披，帶著醉意；「白帝子／赤帝子」：五行相生相剋符號體系；「自負日益畏之」：樹立神聖領袖威望。\\n【政治神話學】將歷史上的平民暴動包裝為火克金的天命更替，極大鼓舞了起義隊伍的必勝信念。"
      }
