      "canonicalText": "秦始皇帝常曰「東南方有天子氣」，於是因東遊以厭之。高祖即自疑，亡匿，隱於芒、碭山澤間。呂後與人俱求，常得之。高祖怪問之，呂後曰：「季所居上常有雲氣，故從往常得季。」高祖心益喜。沛中子弟或聞之，多欲附者矣。",
