      "readingAid": {
        "translation": "等到陳涉（陳勝）在大澤鄉揭竿起義之後，沛縣縣令恐慌之中也打算獻出沛縣響應起義。縣丞掾史蕭何、主吏曹參進諫縣令說：您身為大秦朝廷命官，如今突然打算背叛秦朝、率領沛縣本地子弟起事，大家恐怕不會心服聽從您的命令。希望您能召回那些逃亡在外的沛縣豪傑亡命之徒，能招攬到幾百人，借重他們的力量來震懾脅迫全城大眾，大家就再也不敢不聽從命令了。縣令採納了建議，派遣樊噲前往芒碭山召回高祖。高祖此時聚集的武裝隊伍已經發展到了數百人之眾！",
        "analysis": "【篇旨與陳涉起義蕭何曹參定策召劉邦】陳勝起義引發全國震盪，沛令欲反，蕭何、曹參策劃召回劉邦芒碭山武裝以震懾全城，展現基層官吏與江湖武裝之巧妙策應。\\n【詞義訓詁】「掾、主吏」：秦代縣府核心文官職位；「劫眾」：以武力威懾凝聚渙散民心；「樊噲召高祖」：核心心腹網絡穿針引線。\\n【制度與政變分析】蕭何、曹參身為體制內文吏，深知體制官員缺乏號召力，精準引進劉邦之江湖武裝力量實現政權轉換。"
      }
