      "readingAid": {
        "translation": "沛縣縣令隨後心中反悔恐懼，害怕高祖這幫亡命之徒進城後會引發兵變奪權，於是下令關閉城門，並打算祕密誅殺蕭何與曹參。蕭何、曹參驚恐萬分，連夜翻越城牆逃出城去投奔高祖。高祖於是率領部隊駐紮在沛縣城北，將書信綁在箭桿上射入城牆之內，誠懇告誡沛縣父老說：全天下天下百姓深受暴秦嚴刑苛法苦害太久了！如今各位父老鄉親縱然替沛縣縣令死守城池，天下各路諸侯大軍早晚必定會殺到此地，到那時沛縣必將慘遭屠城浩劫！如今大家若能共同誅殺縣令，推選本地值得擁戴的賢能之人立為首領，以此響應天下諸侯義兵，那麼大家的家族家室就能得以萬全保全；如果不這樣做，全城父子老小都將被血腥屠殺，那樣做是毫無意義白白送死啊！沛縣父老被深深打動，於是率領全城子弟合力攻殺了縣令，打開城門熱情迎接高祖進城，打算擁戴高祖出任沛縣縣令。高祖謙遜推辭說：如今全天下大亂風雲動盪，各路諸侯紛紛起兵爭雄，如今如果主帥將領選拔不當，一旦戰敗必將落得個一敗塗地粉身碎骨的下場！我絕非膽怯自私珍惜自身性命，實在是害怕自己能力才幹微薄，無法保全全體父兄子弟的身家性命。這是性命攸關的天下大事，希望大家重新商議推選更加合適的英才！蕭何、曹參等人全都是體制內的文職官吏，顧惜自身與家族安全，害怕起義一旦失敗將來秦朝朝廷會誅滅九族，於是竭盡全力極力推舉高祖擔當主帥。全城父老也紛紛高呼說：我們平生聽聞過劉季身上的種種神異傳說，命中註定大富大貴，而且占卜卦象沒有誰能比劉季更加大吉大利的了！高祖再三謙遜讓賢，全場眾人沒有誰敢挺身擔當，於是正式擁立高祖為沛公。高祖在沛縣縣衙中庭隆重設壇祭祀黃帝，祭祀戰神蚩尤，軍隊的旗幟旌旗全部採用鮮豔的赤紅色。正是因為當年所斬殺的巨蛇為白帝之子、而斬蛇者為赤帝之子，所以全軍崇尚赤紅之色。自此之後，前來誓死追隨高祖的沛縣子弟迅速擴充到了兩三千人之眾！",
        "analysis": "【篇旨與射書沛城殺令起義立沛公祠黃帝祭蚩尤尚赤】沛縣起義完整歷史進程——劉邦射書曉以利害瓦解民心，蕭曹推賢避禍，劉邦三讓後登位「沛公」，祭祀黃帝蚩尤、旗幟尚赤，正式建立反秦武裝體系。\\n【詞義訓詁】「一敗塗地」：成語典故出處，形容慘敗至肝腦塗地；「祠黃帝祭蚩尤」：繼承華夏兵法祭祀正統；「尚赤」：確立赤帝火德之官方軍旗顏色。\\n【政治博弈分析】蕭曹文吏自愛推劉邦承擔政治風險，劉邦以退為進確立絕對領袖地位，展現出極其高超的羣眾心理掌控與政治動員能力。"
      }
