      "order": 14,
      "canonicalText": "沛公還軍沛，使魏人周市略地。周市使人謂雍齒曰：「豐，故梁徙也。趙逮梁地已定。今豐下魏，魏以齒為侯；不下，且屠豐。」雍齒素不欲屬沛公，及魏招之，即反，以豐降魏。沛公還攻豐，不能下。沛公病，還之沛。",
