        "translation": "沛公班師返回沛縣，派魏國人周市前去奪取周邊土地。魏將周市派使者前來威脅勸降雍齒說：豐邑原本就是當年魏國遷徙遺民所居之地。如今趙國與魏國故地大多已經被平定。如果現在豐邑歸降魏國，魏國將正式冊封您雍齒為列侯；如果不肯歸降，魏國大軍隨後將血洗屠滅豐邑！雍齒平素就心懷傲慢不甘心臣服歸屬沛公，等到魏國使者前來誘降，便當場發動叛變，獻出豐邑投降了魏國。沛公聞訊大怒回師猛攻豐邑，久攻不下。恰在此時沛公身患重病，無奈之下只得暫時撤軍返回沛縣休整。",
