      "canonicalText": "沛公將兵同項羽攻城陽，屠之。東破秦軍於亢父。七月，與項羽同攻東阿，大破秦軍。與項羽分兵，沛公西攻定陶，破之。又西與項羽並力攻雍丘，大破秦軍，斬李由。",
