      "order": 20,
      "canonicalText": "初，懷王與諸將約，先入定關中者王之。當是時，秦兵彊，常乘勝逐北，諸將莫利先入關。獨羽怨秦破項梁，奮勢，願與沛公西入關。懷王諸老將皆曰：「項羽為人慓悍禍賊，嘗攻襄城，襄城無唣類，所過無不殘滅。且楚數進取，前陳王、項梁皆敗，不如更遣長者扶義而西，告諭秦父兄。秦父兄苦其主久矣，今誠得長者往，毋侵暴，宜可下。項羽不可遣，獨沛公素寬大長者。」卒不許羽，而遣沛公西收陳王、項梁散卒。乃道碭至陽城與槓裏，攻秦軍壁，破其二軍。",
