      "readingAid": {
        "translation": "當初，楚懷王同各路將領共同立下盟約：誰先率軍攻入並平定關中秦國本土，就封誰為關中王（先入定關中者王之）！在那時，秦朝正規軍實力依然無比強大，經常乘勝追擊潰滅義軍，各路將領沒有誰認為先入關是件有利可圖的美差。唯獨項羽極度深恨秦軍殺死了叔父項梁，羣情奮發，主動請求願意同沛公一同西征攻入關中。楚懷王麾下的諸位老將紛紛勸阻進諫說：項羽為人生性兇悍殘暴（慓悍禍賊），曾攻打襄城將全城百姓殘酷屠殺雞犬不留（無噍類），所過之處無不殘暴毀滅。況且楚軍多次盲目冒進，先前的陳王陳勝、大帥項梁全都慘遭兵敗身死，如今不如改派一位德高望重的仁厚長者，高舉仁義大旗西征，沿途向秦國父老鄉親宣傳開導政治政策。秦國百姓深受其暴君苛法殘害太久了，如今如果真能得到一位寬厚長者率軍前往，嚴禁部隊侵犯暴虐百姓，應當可以順利招撫攻下關中。項羽性情殘暴絕對不可派遣，唯獨沛公平素就是一位寬厚仁愛、深得民心的仁厚長者！楚懷王最終堅決不允許項羽西征，而專門派遣沛公率軍西進，沿途收編陳勝、項梁失散的潰兵殘卒。沛公於是取道碭縣抵達陽城與槓裏，大膽進攻秦軍營壘，一舉擊潰了秦軍兩大軍團！",
        "analysis": "【篇旨與懷王先入關中者王之約遣寬大長者沛公西征】楚懷王立下「懷王之約」，楚國元老群臣精準洞察項羽「慓悍禍賊襄城無噍類」與劉邦「素寬大長者」，力主遣劉邦扶義西征，奠定漢興定鼎關中之最高決策！\\n【詞義訓詁】「先入定關中者王之」：楚漢爭霸核心政治博弈契約；「無唣類」：唣通噍，嚼也；連能嚼食物的活物都不留，比喻屠城雞犬不留；「寬大長者」：劉邦最具號召力的政治人格形象。\\n【戰略決策論】楚懷王與老將們的政治判斷極其精準——攻打關中秦人本土必須依託仁政宣傳與羣眾路線，項羽的嗜殺只會激起秦人殊死抵抗，劉邦的寬大則能實現和平受降。"
      }
