        "translation": "秦三年十月，齊國將領田都背叛田榮，率領軍隊前去援助項羽解救趙國。沛公在成武攻破了秦朝東郡都尉的部隊。十一月，項羽在安陽果斷斬殺了猶豫不決的上將軍宋義，吞併其軍隊強渡黃河，自立為楚軍上將軍，英布（黥布）等各路猛將全部歸屬項羽麾下。十二月，沛公率軍抵達栗縣，遭遇剛武侯部隊，果斷奪取並收編其四千餘人部隊，隨後與魏國將領皇欣、武滿的軍隊合兵，共同進攻秦軍並大破之。前齊王田建的孫子田安攻下濟北，跟隨項羽北上救趙。項羽在鉅鹿城下發動驚天動地的破釜沉舟決戰，大破秦軍主力，生擒王離，打得章邯全軍潰退！",
        "analysis": "【篇旨與項羽殺宋義破釜沉舟鉅鹿大捷劉邦進軍栗縣收編部隊】記錄秦三年十月至十二月楚漢雙線並進之軍事奇蹟——項羽殺宋義破釜沉舟於鉅鹿破秦軍俘王離，劉邦在河南轉戰收編部隊壯大實力。\\n【詞義訓詁】「殺宋義自立為上將軍」：項羽奪取軍權重塑楚軍戰鬥力；「奪其軍並之」：劉邦果斷兼併雜牌武裝充實主力；「鉅鹿大破秦軍」：擊碎秦帝國最後的軍事支柱。\\n【戰略呼應】項羽在河北牽制並摧毀秦軍主力，為劉邦在河南的快速西進創造了決定性掩護。"
