      "id": "han-shu_ch-1_p-22",
      "chapterId": "han-shu_ch-1",
      "order": 22,
      "canonicalText": "二月，沛公從碭北攻昌邑，遇彭越。越助攻昌邑，未下。沛公西過高陽，酈食其為裏監門，曰：「諸將過此者多，吾視沛公大度。」乃求見沛公。沛公方踞牀，使兩女子洗。酈生不拜，長揖曰：「足下必欲誅無道秦，不宜踞見長者。」於是沛公起，攝衣謝之，延上坐。食其說沛公襲陳留。沛公以為廣野君，以其弟商為將，將陳留兵。三月，攻開封，未拔。西與秦將楊熊會戰白馬，又戰曲遇東，大破之。楊熊走之滎陽，二世使使斬之以徇。四月，南攻潁川，屠之。因張良遂略韓地。",
