      "readingAid": {
        "translation": "二月，沛公從碭縣向北攻打昌邑，在途中遇見彭越。彭越主動協助攻打昌邑，未能攻克。沛公隨後引兵向西路過高陽，高陽隱士酈食其當時擔任鄉里看守城門的小吏（裏監門），對人說：路過這裡的各路諸侯將領極多，但我冷眼觀察唯獨沛公胸懷最為寬宏大度！於是主動前來求見沛公。沛公當時正傲慢地盤腿坐在胡牀上（踞牀），讓兩名年輕侍女給自己洗腳。酈食其走進來不依常禮下拜，只是微微長揖拱手抗議道：閣下如果真的一心想誅滅暴虐無道的暴秦，就不應當如此傲慢地坐著洗腳接見長者！沛公聽後如夢初醒立刻站起身來，整理好衣服向酈生當面道歉謝罪，恭敬地引導他登上首席正座。酈食其隨即獻上妙策勸說沛公突襲奪取秦軍存糧重鎮陳留。沛公採納其計奪得陳留大批糧草，冊封酈食其為廣野君，並任命他的弟弟酈商為將軍，統率陳留降軍。三月，攻打開封未能攻下；向西與秦將楊熊在白馬展開大戰，隨後又在曲遇以東交戰，大破秦軍！楊熊兵敗狼狽逃往滎陽，秦二世派特使當場將楊熊斬首示眾。四月，沛公向南進攻潁川，攻克後屠其頑抗守軍；並通過張良的引導順利奪取平定了韓國故地。",
        "analysis": "【篇旨與酈食其高陽狂生踞牀洗腳奪陳留張良平韓地】記錄沛公結識著名謀士酈食其——高陽狂生折服踞牀洗腳之沛公，智取陳留奪天下糧倉；隨後白馬曲遇破楊熊，在張良協助下經略韓國故地。\\n【詞義訓詁】「裏監門」：鄉里看守門戶之微職，實為隱世奇才；「踞牀使兩女子洗」：沛公早期江湖習氣；「攝衣謝之」：知錯立改、尊賢容士之超強糾錯力；「廣野君」：酈食其首獲封號。\\n【人才格局】沛公能迅速克服自身傲慢習氣，以最高禮遇接納各階層謀臣策士，使其智謀得以全面釋放。"
      }
