      "id": "han-shu_ch-1_p-23",
      "chapterId": "han-shu_ch-1",
      "order": 23,
      "canonicalText": "時趙別將司馬卬方欲渡河入關，沛公乃北攻平陰，絕河津。南，戰雒陽東，軍不利，從轘轅至陽城，收軍中馬騎。六月，與南陽守齮戰犨東，大破之。略南陽郡，南陽守走，保城守宛。沛公引兵過宛西。張良諫曰：「沛公雖欲急入關，秦兵尚眾，距險。今不下宛，宛從後擊，彊秦在前，此危道也。」於是沛公乃夜引軍從他道還，偃旗幟，遲明，圍宛城三匝。南陽守欲自剄，其舍人陳恢曰：「死未晚也。」乃踰城見沛公，曰：「臣聞足下約先入鹹陽者王之，今足下留守宛。宛郡縣連城數十，其吏民自以為降必死，故皆堅守乘城。今足下盡日止攻，士死傷者必多；引兵去宛，宛必隨足下。足下前則失鹹陽之約，後有彊宛之患。為足下計，莫若約降，封其守，因使止守，引其甲卒與之西。諸城未下者，聞聲爭開門而待足下，足下通行無所累。」沛公曰：「善。」七月，南陽守齮降，封為殷侯，封陳恢千戶。引兵西，無不下者。至丹水，高武侯鰓、襄侯王陵降。還攻胡陽，遇番君別將梅鋗，與偕攻析、酈，皆降。所過毋得鹵掠，秦民喜。遣魏人甯昌使秦。是月章邯舉軍降項羽，羽以為雍王。瑕丘申陽下河南。",
