      "canonicalText": "八月，沛公攻武關，入秦。秦相趙高恐，乃殺二世，使人來，欲約分王關中，沛公不許。九月，趙高立二世兄子子嬰為秦王。子嬰誅滅趙高，遣將將兵距嶢關。沛公欲擊之，張良曰：「秦兵尚彊，未可輕。願先遣人益張旗幟於山上為疑兵，使酈食其、陸賈往說秦將，啗以利。」秦將果欲連和，沛公欲許之。張良曰：「此獨其將欲叛，恐其士卒不從，不如因其怠懈擊之。」沛公引兵繞嶢關，踰蕢山，擊秦軍，大破之藍田南。遂至藍田，又戰其北，秦兵大敗。",
