      "canonicalText": "元年冬十月，五星聚於東井。沛公至霸上。秦王子嬰素車白馬，係頸以組，封皇帝璽符節，降枳道旁。諸將或言誅秦王，沛公曰：「始懷王遣我，固以能寬容，且人已服降，殺之不祥。」乃以屬吏。遂西入鹹陽，欲止宮休舍，樊噲、張良諫，乃封秦重寶財物府庫，還軍霸上。蕭何盡收秦丞相府圖籍文書。十一月，召諸縣豪桀曰：「父老苦秦苛法久矣，誹謗者族，耦語者棄市。吾與諸侯約，先入關者王之，吾當王關中。與父老約，法三章耳：殺人者死，傷人及盜抵罪。餘悉除去秦法。吏民皆按堵如故。凡吾所以來，為父兄除害，非有所侵暴，毋恐！且吾所以軍霸上，待諸侯至而定要束耳。」乃使人與秦吏行至縣鄉邑告諭之。秦民大喜，爭持牛羊酒食獻享軍士。沛公讓不受，曰：「倉粟多，不欲費民。」民又益喜，唯恐沛公不為秦王。",
