      "canonicalText": "或說沛公曰：「秦富十倍天下，地形彊。今聞章邯降項羽，羽號曰雍王，王關中。即來，沛公恐不得有此。可急使守函谷關，毋內諸侯軍，稍徵關中兵以自益，距之。」沛公然其計，從之。十二月，項羽果帥諸侯兵欲西入關，關門閉。聞沛公已定關中，羽大怒，使黥布等攻破函谷關，遂至戲下。沛公左司馬曹毋傷聞羽怒，欲攻沛公，使人言羽曰：「沛公欲王關中，令子嬰相，珍寶盡有之。」欲以求封。亞父范增說羽曰：「沛公居山東時，貪財好色，今聞其入關，珍物無所取，婦女無所幸，此其志不小。吾使人望其氣，皆為龍，成五色，此天子氣。急擊之，勿失。」於是饗士，旦日合戰。是時，羽兵四十萬，號百萬。沛公兵十萬，號二十萬，力不敵。會羽季父左尹項伯素善張良，夜馳見張良，具告其實，欲與俱去，毋特俱死。良曰：「臣為韓王送沛公，不可不告，亡去不義。」乃與項伯俱見沛公。沛公與伯約為婚姻，曰：「吾入關，秋豪無所敢取，籍吏民，封府庫，待將軍。所以守關者，備他盜也。日夜望將軍到，豈敢反邪！願伯明言不敢背德。」項伯許諾，即夜復去。戒沛公曰：「旦日不可不早自來謝。」項伯還，具以沛公言告羽，因曰：「沛公不先破關中兵，公巨能入乎？且人有大功，擊之不祥，不如因善之。」羽許諾。",
