      "readingAid": {
        "translation": "有人向沛公獻策說：關中秦國的富饒程度是全天下的十倍，地理地形極其險要堅固。如今聽聞秦將章邯已經投降了項羽，項羽私自封他為雍王，許諾讓他稱王關中。項羽大軍一旦殺到，沛公恐怕就無法繼續佔有這片土地了。您應當緊急派遣軍隊封鎖扼守函谷關天險，嚴禁各路諸侯大軍入關，同時在關中逐步徵召秦人入伍以充實擴充自己的軍隊，堅決抵禦諸侯軍！沛公認為這個計策有理，採納並照辦了。十二月，項羽果然率領四十萬諸侯聯軍浩浩蕩蕩企圖向西入關，卻發現函谷關大門緊閉嚴防死守。聽聞沛公早已平定關中全境，項羽勃然大怒，下令猛將英布（黥布）等人強攻攻破函谷關，大軍長驅直入推進駐紮在戲水之畔。沛公軍中的左司馬曹無傷聽聞項羽雷霆震怒打算進攻沛公，為了向項羽邀功求取封侯，暗中派遣特使向項羽告密告發說：沛公如今妄圖獨霸關中稱王，任命降王子嬰為相國，將秦宮全部奇珍異寶全部據為己有！謀士亞父范增趁機極力勸說項羽說：沛公當年居住在崤山以東時，生性極其貪財好色；如今聽聞他攻入關中後，金銀財寶秋毫無所取，後宮美女沒有碰過一人，這說明他的志向野心大得不可估量啊！我曾特地派遣方士望其頭頂雲氣，全都是五彩巨龍盤旋之象，這正是貨真價實的至尊天子之氣啊！必須抓緊在黎明發動雷霆進攻徹底將他殲滅，千萬不可錯失良機！項羽於是下令殺牛宰羊犒賞全軍將士，下令明天拂曉全軍出擊與沛公決戰。當時項羽麾下兵力多達四十萬人，對外號稱百萬雄師；而沛公兵力僅有十萬人，對外號稱二十萬，雙方軍事實力對比懸殊根本不可同日而語。恰在此千鈞一發之際，項羽的小叔父、楚國左尹項伯平素與張良交情極深，連夜單騎飛馳趕到霸上沛公軍營私會張良，將項羽即將發動總攻的驚天祕密全盤相告，苦苦相勸張良同他一同連夜逃走，切莫留在軍中白白送死。張良義正辭嚴地說：我當年受韓王派遣護送沛公入關，如今大難臨頭不可不將實情相告，背叛沛公私自逃亡是極其不義的行徑！張良隨即引導項伯一同面見沛公。沛公熱情萬分地接待項伯，當場與項伯約定結為兒女親家（約為婚姻），指天發誓洗白說：我自從攻入關中以來，連秋天鳥獸身上新生的細毛那樣微薄之物都不敢私自佔有一絲一毫（秋豪無所敢取）！造冊登記官吏戶籍百姓，原封不動查封國庫府庫，整天眼巴巴在此恭敬等候項將軍大駕光臨！我之所以派兵扼守函谷關，純粹是為了防備其他盜匪流寇作亂罷了。我日日夜夜盼望著將軍大駕光臨，又怎麼可能膽敢背叛反抗呢！懇求伯父回到軍中務必替我向項將軍極力澄清，我劉邦絕不敢忘恩負義背德啊！項伯鄭重答應許諾，當天深夜再次策馬飛馳返回項羽軍營。臨走前嚴肅告誡沛公說：明天一早您務必親自儘早前來鴻門當面向項王賠罪謝罪！項伯回到軍營後，把沛公的這番誠懇表態一字不差地轉告給項羽，並順勢開導進言說：如果不是沛公先期攻破關中秦軍主力，將軍您今天難道能如此輕易暢通無阻地進入關中嗎？更何況人家立下了蓋世大功，如今反而興兵討伐攻打人家是極其不吉利不義的，不如趁此機會厚待善待他！項羽聽後點頭答應了。",
        "analysis": "【篇旨與函谷關閉項羽大怒范增望氣曹無傷告密項伯夜馳救張良】鴻門宴前夕之驚天危機——劉邦聽人言封函谷關拒諸侯，項羽破關至戲下，曹無傷告密，范增望氣「皆為龍成五色天子氣急擊勿失」；項伯夜訪張良、劉邦約為婚姻秋毫無敢取，化解拂曉大決戰危機！\\n【詞義訓詁】「毋內諸侯軍」：內通納，不接納諸侯大軍入關；「望其氣皆為龍成五色」：先秦漢代占星望氣術；「籍吏民封府庫」：展現清廉自守之政治表態；「約為婚姻」：政治聯姻化解滅頂之災。\\n【危機公關與情報網絡】張良與項伯的生死之交打破了西楚嚴密的情報封鎖，劉邦以超凡的低姿態與利益捆綁瓦解了項羽陣營的進攻意志。"
      }
