      "order": 27,
      "canonicalText": "沛公旦日從百餘騎見羽鴻門，謝曰：「臣與將軍戮力攻秦，將軍戰河北，臣戰河南，不自意先入關，能破秦，與將軍復相見。今者有小人言，令將軍與臣有隙。」羽曰：「此沛公左司馬曹毋傷言之，不然，籍何以生此？」羽因留沛公飲。范增數目羽擊沛公，羽不應。范增起，出謂項莊曰：「",
