      "order": 28,
      "canonicalText": "君王為人不忍，汝入以劍舞，因擊沛公，殺之。不者，汝屬且為所虜。」莊入為壽。壽畢，曰：「軍中無以為樂，請以劍舞。」因拔劍舞。項伯亦起舞，常以身翼蔽沛公。樊噲聞事急，直入，怒甚。羽壯之，賜以酒。噲因譙讓羽。有頃，沛公起如廁，招樊噲出，置車官屬，獨騎，與樊噲、靳彊、滕公、紀成步，從間道走軍，使張良留謝羽。羽問：「沛公安在？」曰：「聞將軍有意督過之，脫身去，間至軍，故使臣獻璧。」羽受之。又獻玉斗范增。增怒，撞其鬥，起曰：「吾屬今為沛公虜矣！」",
