      "readingAid": {
        "translation": "君王（項羽）為人心慈手軟不忍心下手，你現在立刻進去為大家敬酒祝壽，藉機請求舞劍助興，趁機一劍刺殺沛公！否則的話，我們這幫人日後早晚全都要淪為他的階下囚虜啊！項莊於是快步走進大帳敬酒祝壽。祝壽完畢後說：軍營之中沒有什麼歌舞娛樂節目，請允許我拔劍起舞為各位貴客助興吧！隨即拔出佩劍在大帳中央寒光閃閃起舞。項伯見狀也立刻拔劍起舞，每一次都用自己的身體像鳥兒展翅一樣死死遮擋掩護沛公（常以身翼蔽沛公）。大將樊噲在帳外聽聞帳內形勢萬分危急，手持鐵盾直接怒目圓睜闖入大帳，神色威嚴憤怒到了極點！項羽見狀由衷讚嘆他是個勇冠三軍的豪傑壯士，當場賜給他一大斗美酒與一整隻生豬腿。樊噲拔劍切肉痛飲，趁機當面慷慨陳詞痛斥責備項羽不守信義！過了一會兒，沛公藉口起身上廁所，悄悄招手示意樊噲一同走出大帳；果斷拋棄了馬車與隨行官屬，劉邦親自單獨騎上一匹快馬，由樊噲、靳彊、夏侯嬰（滕公）、紀成四名心腹猛將手持盾牌步兵護衛，從小路小徑飛奔逃回霸上軍營！留下張良單獨留在帳中向項羽謝罪善後。項羽過後詢問：沛公現在人在哪裡？張良回答說：沛公聽聞將軍有意要追究責備他的過失，不勝酒力先行脫身離席，現在恐怕已經從小路安全返回霸上軍營了，所以特地命令微臣向將軍奉獻白璧一雙！項羽坦然接受了白璧。張良隨即又向范增進獻玉斗一隻。范增勃然大怒，拔出寶劍當場將玉斗砍得粉碎砸在地上，憤然離席怒斥道：唉！豎子不足與謀！我們這幫人將來必定全都要淪為沛公的俘虜啊！",
        "analysis": "【篇旨與項莊舞劍項伯翼蔽樊噲闖帳尿遁逃生范增碎鬥】鴻門宴千古高潮絕唱——項莊舞劍意在沛公、項伯翼蔽、樊噲闖帳譙讓項羽、劉邦藉如廁由間道脫身、張良留謝獻璧碎鬥，范增發出「吾屬今為沛公虜矣」之千古預言！\\n【詞義訓詁】「以身翼蔽」：如鳥張翼掩護；「置車官屬」：果斷斷尾求生；「撞其鬥」：拔劍斬碎玉斗洩憤；「豎子不足與謀」：對項羽政治幼稚之絕望痛罵。\\n【危機公關與逃生決策】劉邦在生死邊緣精準利用項羽虛榮心、項伯內應與樊噲勇猛，果斷棄車保帥、由間道逃生，完成世界政治史上最驚險的死裡逃生。"
      }
