      "canonicalText": "沛公歸數日，羽引兵西屠鹹陽，殺秦降王子嬰，燒秦宮室，所過無不殘滅。秦民大失望。羽使人還報懷王，懷王曰：「如約。」羽怨懷王不肯令與沛公俱西入關，而北救趙，後天下約。乃曰：「",
