      "readingAid": {
        "translation": "沛公安全返回霸上軍營數天之後，項羽率領四十萬大軍長驅直入開進鹹陽城，隨即大開殺戒殘酷屠戮鹹陽百姓，殘忍殺害了已經投降歸順的秦王子嬰，縱火焚燒了秦朝阿房宮與皇宮宮室，大火連月不熄，大軍所過之處無不殘暴毀滅！關中秦國百姓對項羽大失所望徹底絕望。項羽派遣使者返回彭城向楚懷王報告勝利，楚懷王堅決批覆回答說：一切嚴格依照當初的盟約辦理（先入關者王之）！項羽內心極度怨恨楚懷王當年不肯讓自己同沛公一同西征入關、反而派自己北上救趙，致使自己落後於當初的天下稱王之約。項羽於是公然叫囂說道：。",
        "analysis": "【篇旨與項羽屠鹹陽殺子嬰燒宮室秦民失望懷王如約】項羽入鹹陽後大肆屠殺掠奪、殺子嬰、燒宮室，與劉邦約法三章秋毫無犯形成強烈道德反差，關中民心自此徹底背離項羽；懷王堅持「如約」，引爆項羽分封逆流。\\n【詞義訓詁】「屠鹹陽殺子嬰燒宮室」：項羽政治不成熟之暴虐宣洩；「秦民大失望」：政治合法性與民心向背之根本逆轉；「如約」：楚懷王試圖以名義體制壓制項羽。\\n【政治得失對比】軍事上的勝利無法彌補政治上的自絕於民，項羽焚掠鹹陽自毀關中根據地，為其最終敗亡埋下伏筆。"
      }
