      "chapterId": "han-shu_ch-1",
      "order": 30,
      "canonicalText": "懷王者，吾家所立耳，非有功伐，何以得專主約！本定天下，諸將與籍也。」春正月，陽尊懷王為義帝，實不用其命。",
