      "order": 31,
      "canonicalText": "二月，羽自立為西楚霸王，王梁、楚地九郡，都彭城。背約，更立沛公為漢王，王巴、蜀、漢中四十一縣，都南鄭。三分關中，立秦三將：章邯為雍王，都廢丘；司馬欣為塞王，都櫟陽；董翳為翟王，都高奴。候、將有功者，皆封為王。",
