      "id": "han-shu_ch-1_p-35",
      "chapterId": "han-shu_ch-1",
      "order": 35,
      "canonicalText": "韓信亡楚歸漢，未知名。為連敖，坐法當斬，信亡去，得滕公。滕公奇其言，壯其貌，說漢王，漢王以為治粟都尉，信亦未自奇。信數與蕭何語，何奇之。漢王至南鄭，諸將及士卒皆歌謳思歸，多道亡。信復亡去，何聞之，不及以聞，自追之。人告漢王曰「丞相何亡」，漢王大怒，如失左右手。居一二日，何來謁。漢王且怒且喜，罵何曰：「若亡，何也？」何曰：「臣不敢亡，追亡者耳。」曰：「追誰？」曰：「韓信。」漢王復罵曰：「諸將亡者以數十，公無所追；追信，妄也！」何曰：「諸將易得，至如信，國士無雙。王必欲長王漢中，無所事信；必欲爭天下，非信無可與計事者。顧王策安所決耳！」王曰：「吾亦欲東耳，安能鬱鬱久居此！」何曰：「王計必東，能用信，信即留；不能用信，終亡耳。」王曰：「吾為公以為將。」何曰：「雖為將，信不留。」王曰：「以為大將。」何曰：「幸甚！」於是王欲召信拜之。何曰：「王素慢無禮。今拜大將，如呼小兒，此乃信所以去也。王必欲拜之，擇良日，齋戒，設壇場，具禮，乃可。」王許之。諸將皆喜，人人各自以為得大將。至拜，乃韓信也，一軍皆驚。",
