      "readingAid": {
        "translation": "八月，漢王劉邦率領漢軍主力從險峻的故道祕密殺出（明修棧道、暗度陳倉），出其不意閃電奔襲雍國。雍王章邯倉促率軍在陳倉迎擊漢軍，雍軍被打得大敗潰退；雙方在好畤再次交戰，章邯再次慘敗，狼狽逃回國都廢丘固守。漢王隨即順利平定了雍國全境土地。漢軍主力向東推進抵達鹹陽，分兵包圍廢丘的雍王章邯，同時派遣各路將領向四方攻城略地。塞王司馬欣、翟王董翳眼見大勢已去紛紛開城投降漢王，漢王將其領地改設為漢朝直轄的渭南郡、河上郡與上郡。向西揮師平定了隴西臨洮。",
        "analysis": "【篇旨與暗度陳倉平定三秦章邯退保廢丘欣翳投降】韓信拜將後第一場經典戰役——漢軍暗度陳倉閃電奇襲，陳倉、好畤兩戰擊潰章邯，塞王欣、翟王翳望風歸降，漢王以迅雷不及掩耳之勢平定三秦全境。\\n【詞義訓詁】「從故道出」：暗度陳倉之地理路線；「圍廢丘」：章邯退保孤城；「以其地為郡」：迅速將三秦改為漢朝直轄郡縣。\\n【戰略實施】漢軍跳出漢中地理囚籠，以迅猛攻勢一舉奪取八百里秦川戰略基地，完成楚漢爭霸第一階段戰略突圍。"
      }
