      "id": "han-shu_ch-1_p-41",
      "chapterId": "han-shu_ch-1",
      "order": 41,
      "canonicalText": "春正月，羽擊田榮城陽，榮敗走平原，平原民殺之。齊皆降楚，楚焚其城郭，齊人復畔之。諸將拔北地，虜雍王弟章平。赦罪人。二月癸未，令民除秦社稷，立漢社稷。施恩德，賜民爵。蜀漢民給軍事勞苦，復勿租稅二歲。關中卒從軍者，復家一歲。舉民年五十以上，有脩行，能帥眾為善，置以為三老，鄉一人。擇鄉三老一人為縣三老，與縣令丞尉以事相教，復勿繇戍。以十月賜酒肉。",
