      "id": "han-shu_ch-1_p-42",
      "chapterId": "han-shu_ch-1",
      "order": 42,
      "canonicalText": "三月，漢王自臨晉渡河，魏王豹降，將兵從。下河內，虜殷王卬，置河內郡。至脩武，陳平亡楚來降。漢王與語，說之，使參乘，監諸將。南渡平陰津，至洛陽，新城三老董公遮說漢王曰：「臣聞『順德者昌，逆德者亡』，『兵出無名，事故不成』。故曰：『明其為賊，敵乃可服。』項羽為無道，放殺其主，天下之賊也。夫仁不以勇，義不以力，三軍之眾為之素服，以告之諸侯，為此東伐，四海之內莫不仰德。此三王之舉也。」漢王曰：「善，非夫子無所聞。」於是漢王為義帝發喪，袒而大哭，哀臨三日。發使告諸侯曰：「",
