      "id": "han-shu_ch-1_p-44",
      "chapterId": "han-shu_ch-1",
      "order": 44,
      "canonicalText": "夏四月，田榮弟橫收得數萬人，立榮子廣為齊王。羽雖聞漢東，既擊齊，欲遂破之而後擊漢，漢王以故得劫五諸侯兵，東伐楚。到外黃，彭越將三萬人歸漢。漢王拜越為魏相國，令定梁地。漢王遂入彭城，收羽美人貨賂，置酒高會。羽聞之，令其將擊齊，而自以精兵三萬人從魯出胡陵，至蕭，晨擊漢軍，大戰彭城靈壁東睢水上，大破漢軍，多殺士卒，睢水為之不流。圍漢王三匝。大風從西北起，折木發屋，揚砂石，晝晦，楚軍大亂，而漢王得與數十騎遁去。過沛，使人求室家，室家亦已亡，不相得。漢王道逢孝惠、魯元，載行。楚騎追漢王，漢王急，推墮二子。滕公下收載，遂得脫。審食其從太公、呂後間行，反遇楚軍，羽常置軍中以為質。諸侯見漢敗，皆亡去。塞王欣、翟王翳降楚，殷王卬死。",
