      "chapterId": "han-shu_ch-1",
      "order": 45,
      "canonicalText": "呂後兄周呂侯將兵居下邑，漢王往從之。稍收士卒，軍碭。",
      "sentenceIds": [
        "han-shu_ch-1_p-45_s-1",
        "han-shu_ch-1_p-45_s-2"
      ],
      "sourceRefs": [
        {
          "label": "中國哲學書電子化計劃《漢書・高帝紀》",
          "edition": "中華書局點校本／顏師古注本",
          "url": "https://ctext.org/han-shu/gao-di-ji/zh"
        },
        {
          "label": "維基文庫《漢書・高帝紀》",
          "edition": "百衲本二十四史／四庫全書史部正史類",
          "url": "https://zh.wikisource.org/wiki/漢書/卷001上"
        }
      ],
      "readingAid": {
        "translation": "當時呂後的哥哥周呂侯正率領軍隊駐紮在下邑，漢王（劉邦）在彭城戰敗後便前往那裡投奔他。劉邦在下邑逐漸收集被打散的殘兵敗將，然後將軍隊駐紮在碭縣。",
        "analysis": "【訓詁與名物】：「呂後兄」即呂雉的哥哥呂澤。「周呂侯」呂澤的封號。「將兵」率領軍隊。「下邑」地名。「從之」指前往投奔會合。「稍」指逐漸、漸漸。「收士卒」指收集彭城之戰潰散的士兵。「軍」作動詞，駐紮。「碭（dàng）」地名。\\n\\n【章法與結構】：本段記錄了劉邦一生中最危急時刻（彭城大敗）之後的收攏與喘息。文章先交代了救援力量的位置（呂侯居下邑），接著寫劉邦的投奔（往從之），最後寫局勢的初步穩定（稍收士卒，軍碭）。短短三句，勾勒出了劉邦從潰敗逃亡到重新立足的過程。\\n\\n【思想與義理】：彭城之戰是劉邦起兵以來遭遇的最大一次慘敗，五十六萬大軍灰飛煙滅，劉邦僅率數十騎逃脫。這段記載雖然簡短，卻展現了劉邦集團強大的抗挫折能力與韌性。呂澤的軍隊（下邑）成為了劉邦保命的最後防線。而劉邦在剛剛經歷大敗、驚魂未定之時，就能夠迅速「稍收士卒，軍碭」，穩住陣腳，這證明瞭他卓越的心理素質與部隊號召力。正是這種百折不撓的精神，支撐著他在極度劣勢中最終完成翻盤。"
      }
