      "id": "han-shu_ch-1_p-49",
      "chapterId": "han-shu_ch-1",
      "order": 49,
      "canonicalText": "秋八月，漢王如滎陽，謂酈食其曰：「緩頰往說魏王豹，能下之，以魏地萬戶封生。」食其往，豹不聽。漢王以韓信為左丞相，與曹參、灌嬰俱擊魏。食其還，漢王問：「魏大將誰也？」對曰：「柏直。」王曰：「是口尚乳臭，不能當韓信。騎將誰也？」曰：「馮敬。」曰：「是秦將馮無擇子也，雖賢，不能當灌嬰。步卒將誰也？」曰：「項它。」曰：「是不能當曹參。吾無患矣。」九月，信等虜豹，傳詣滎陽。定魏地，置河東、太原、上黨郡。信使人請兵三萬人，願以北舉燕趙，東擊齊，南絕楚糧道。漢王與之。",
