      "readingAid": {
        "translation": "秋八月，漢王再次親臨滎陽前線，對謀士酈食其說：請先生放寬辭色好好前往遊說魏王魏豹，如果能夠和平勸降他，我將把魏國一萬戶封地冊封給先生！酈食其前往遊說，魏豹堅決不肯聽從。漢王隨即任命大將軍韓信為左丞相，同大將曹參、騎兵名將灌嬰一同率軍北伐攻打魏國。酈食其返回軍營，漢王詳細詢問前線軍情：魏國任命的統帥大將究竟是誰？酈食其回答說：是柏直。漢王冷笑說：這傢夥簡直是嘴上乳臭未乾的小毛孩子（口尚乳臭），根本抵擋不住韓信！魏國的騎兵將領是誰？回答說：是馮敬。漢王說：這是秦朝名將馮無擇的兒子，雖然頗有才幹，但絕對抵擋不住灌嬰！魏國的步兵將領是誰？回答說：是項它。漢王笑道：這人根本抵擋不住曹參。我再也沒有任何可擔憂的了！九月，韓信、曹參等人施展木罌渡河妙計生擒魏王魏豹，用囚車押解至滎陽。韓信徹底平定了魏國全境，改設為河東郡、太原郡與上黨郡。大將軍韓信隨即派特使向漢王請求增撥精兵三萬人，發誓願意率軍一路向北橫掃平定燕國與趙國，向東擊破齊國，向南徹底切斷西楚項羽的全部糧道補給線！漢王毫不猶豫撥給他三萬兵馬。",
        "analysis": "【篇旨與知人善任點評魏將韓信破魏定北伐天下大計】劉邦精闢點評魏將（柏直乳臭、馮敬難當灌嬰、項它難當曹參）展現超凡知人眼光；韓信木罌渡河滅魏，主動請纓北伐燕趙、東破齊、南絕楚糧道，開啟北方大包抄戰略！\\n【詞義訓詁】「緩頰」：委婉勸說；「口尚乳臭」：比喻年輕識淺；「北舉燕趙東擊齊南絕楚糧道」：韓信開闢北方大戰場之宏偉軍事戰略。\\n【戰略大迂迴】韓信獨立領軍開闢北方戰場，與劉邦在滎陽成皋正面抗擊項羽形成完美的「正面牽制、側翼大迂迴」戰略大鉗形攻勢。"
      }
