      "id": "han-shu_ch-1_p-51",
      "chapterId": "han-shu_ch-1",
      "order": 51,
      "canonicalText": "隨何既說黥布，布起兵攻楚。楚使項聲、龍且攻布，布戰不勝。十二月，布與隨何間行歸漢。漢王分之兵，與俱收兵至成皋。",
      "sentenceIds": [
        "han-shu_ch-1_p-51_s-1",
        "han-shu_ch-1_p-51_s-2",
        "han-shu_ch-1_p-51_s-3",
        "han-shu_ch-1_p-51_s-4"
      ],
      "sourceRefs": [
        {
          "label": "中國哲學書電子化計劃《漢書・高帝紀》",
          "edition": "中華書局點校本／顏師古注本",
          "url": "https://ctext.org/han-shu/gao-di-ji/zh"
        },
        {
          "label": "維基文庫《漢書・高帝紀》",
          "edition": "百衲本二十四史／四庫全書史部正史類",
          "url": "https://zh.wikisource.org/wiki/漢書/卷001上"
        }
      ],
      "readingAid": {
        "translation": "隨何成功地說服了黥布（九江王英布）反叛項羽之後，黥布便起兵攻打楚國。楚國派將領項聲、龍且去攻打黥布，黥布戰敗了。到了十二月，黥布和隨何從小路祕密逃行，歸順了漢王。漢王分撥給他一部分軍隊，讓他和自己一起收集殘兵，退守到了成皋。",
        "analysis": "【訓詁與名物】：「隨何」劉邦手下的謀士。「說（shuì）」指遊說。「黥（qíng）布」即英布，因受過黥刑（面上刺字）而得名，原為項羽手下悍將，被封為九江王。「項聲、龍且（jū）」皆為楚軍名將。「間行」指從小路祕密行走，躲避追捕。「成皋（gāo）」即虎牢關，軍事重鎮。\\n\\n【章法與結構】：本段敘事節奏極快，充滿了軍事行動的緊張感。文章按照時間順序展開：先是隨何遊說成功的結果（布攻楚）；接著是項羽的強力鎮壓（楚攻布，布戰不勝）；然後是黥布的潰逃與歸附（間行歸漢）；最後是劉邦的安撫與戰略部署（分兵，收兵至成皋）。幾次轉折，乾淨利落。\\n\\n【思想與義理】：黥布的叛楚歸漢，是楚漢戰爭中雙方實力對比發生轉變的一個重要標誌。英布作為項羽麾下最能打仗的將領之一，他的倒戈不僅直接削弱了楚軍的實力，更在心理上對楚軍造成了巨大打擊。雖然黥布起兵不久就被龍且擊敗，但他成功牽制了楚軍的兵力，減輕了劉邦正面的壓力。劉邦對戰敗來投的黥布沒有嫌棄，反而「分之兵」，展現了他寬廣的胸襟與高超的御人手段。劉邦退守成皋，標誌著楚漢戰爭進入了漫長而殘酷的戰略相持階段。"
      }
