      "chapterId": "han-shu_ch-1",
      "order": 54,
      "canonicalText": "五月，將軍紀信曰：「事急矣！臣請誑楚，可以間出。」於是陳平夜出女子東門二千餘人，楚因四面擊之。紀信乃乘王車，黃屋左纛，曰：「食盡，漢王降楚。」楚皆呼萬歲，之城東觀，以故漢王得與數十騎出西門遁。令御史大夫周苛、魏豹、樅公守滎陽。羽見紀信，問：「漢王安在？」曰：「已出去矣。」羽燒殺信。而周苛、樅公相謂曰：「反國之王，難與守城。」因殺魏豹。",
