      "readingAid": {
        "translation": "五月，滎陽城中糧盡援絕危在旦夕，將軍紀信挺身而出對漢王說：軍情十萬火急！微臣請求假扮大王欺騙楚軍，大王才可以趁亂從小路安全突圍！於是陳平在深夜驅趕滎陽城中兩千多名婦女從東門開門湧出，楚軍以為漢軍突圍紛紛四面合圍撲向東門。隨後紀信親自乘坐著漢王的黃金天子專車（乘王車），車上裝飾著黃色車蓋與左側插著的牛尾大旗（黃屋左纛），向楚軍大聲呼喊道：城中糧食已盡，漢王正式開城投降楚軍！楚軍將士聞訊人人狂呼萬歲歡聲雷動，紛紛湧向城東爭相圍觀；漢王劉邦趁著楚軍主力被東門吸引之際，率領數十名心腹騎兵悄悄打開西門飛馳突圍逃脫！漢王臨行前命令御史大夫周苛、魏豹、樅公留守滎陽。項羽走上前親自接見投降的假漢王，定睛一看發現是紀信，厲聲質問道：真正的漢王究竟在哪裡？紀信傲然回答說：我們漢王早已安全出城遠去了！項羽勃然大怒，下令當場將忠勇的紀信活活放火燒死！而城中的留守將領周苛、樅公私下商議說：魏豹是個反覆無常的叛變之王，極其難以同他同心死守城池！於是在城中當機立斷果斷將魏豹斬殺處死。",
        "analysis": "【篇旨與紀信捨身救主乘黃屋詐降滎陽突圍周苛誅魏豹】楚漢最震撼之忠烈史詩——陳平夜出女子二千誘敵，紀信假扮漢王乘黃屋左纛詐降被項羽燒殺，掩護劉邦西門突圍；周苛樅公果斷誅殺反覆無常之魏豹，消除內應隱患。\\n【詞義訓詁】「黃屋左纛」：纛，音道，天子車駕專屬標誌；「楚皆呼萬歲」：楚軍防線全面被心理欺騙瓦解；「反國之王難與守城」：防範內部叛變的果斷處置。\\n【忠烈與犧牲】紀信捨生取義成為千古忠義圖騰，展現漢軍核心將領對劉邦的崇高忠誠與獻身精神。"
      }
