      "id": "han-shu_ch-1_p-55",
      "chapterId": "han-shu_ch-1",
      "order": 55,
      "canonicalText": "漢王出滎陽，至成皋。自成皋入關，收兵欲復東。轅生說漢王曰：「漢與楚相距滎陽數歲，漢常困。願君王出武關，項王必引兵南走，王深壁，令滎陽成皋間且得休息。使韓信等得輯河北趙地，連燕齊，君王乃復走滎陽。如此，則楚所備者多，力分。漢得休息，復與之戰，破之必矣。」漢王從其計，出軍宛葉間，與黥布行收兵。",
