      "readingAid": {
        "translation": "漢王成功逃出滎陽之後，抵達堅固的成皋要塞。隨後從成皋返回關中，在關中迅速重新徵召集結軍隊打算再次殺向東方。謀士轅生（袁生）向漢王獻上圍魏救趙的戰略妙策說：漢軍與楚軍在滎陽正面對峙僵持了幾年之久，漢軍始終處於被動受困的局面。希望君王這次大軍出關不要直接走函谷關，而是出武關南下宛縣、葉縣一帶！項羽聽聞大王出現在南方，必定會親自率軍向南追擊；大王屆時只管深溝高壘堅守不出（深壁），這樣一來就能讓滎陽、成皋一線的漢軍得到寶貴的喘息休整時間；同時能為北方的韓信爭取充分時間去徹底平定河北趙地、聯絡燕國與進攻齊國！等到北方戰略大包抄佈局完成之後，君王您再率軍重返滎陽成皋。像這樣一來，楚軍需要四處防備的戰線就太多了，其兵力必然會被極度分散削弱；而漢軍得到了充分休整，再次同楚軍決戰，就必定能夠一舉擊破項羽了！漢王全盤採納了轅生的精妙大計，率軍從武關出發進駐宛縣、葉縣一帶，同英布一同沿途招募整訓軍隊。",
        "analysis": "【篇旨與轅生出武關調動項羽聲東擊西大戰略佈局】轅生獻上戰略調動妙策——劉邦出武關屯兵宛葉，成功將項羽主力從滎陽成皋一線調往南方，為正面防線爭取休整、為北方韓信橫掃趙燕齊爭取寶貴戰略時間。\\n【詞義訓詁】「深壁」：構築深溝高壘堅守不戰；「楚所備者多力分」：兵法「備前則後寡、備左則右寡」之精確運用；「行收兵」：沿途招募擴軍。\\n【戰略大機動】劉邦展現出卓越的戰略大局觀，以自身為誘餌牽制項羽主力，盤活了全國整個大棋局。"
      }
