      "id": "han-shu_ch-1_p-56",
      "chapterId": "han-shu_ch-1",
      "order": 56,
      "canonicalText": "羽聞漢王在宛，果引兵南，漢王堅壁不與戰。是月，彭越渡睢，與項聲、薛公戰下邳，破殺薛公。羽使終公守成皋，而自東擊彭越。漢王引兵北，擊破終公，復軍成皋。六月，羽已破走彭越，聞漢復軍成皋，乃引兵西拔滎陽城，生得周苛。羽謂苛：「為我將，以公為上將軍，封三萬戶。」周苛罵曰：「若不趨降漢，今為虜矣！若非漢王敵也。」羽亨周苛，並殺樅公，而虜韓王信，遂圍成皋。漢王跳，獨與滕公共車出成皋玉門，北渡河，宿小脩武。自稱使者，晨馳入張耳、韓信壁，而奪之軍。乃使張耳北收兵趙地。",
