      "id": "han-shu_ch-1_p-57",
      "chapterId": "han-shu_ch-1",
      "order": 57,
      "canonicalText": "秋七月，有星孛於大角。漢王得韓信軍，復大振。八月，臨河南鄉，軍小脩武，欲復戰。郎中鄭忠說止漢王，高壘深塹勿戰。漢王聽其計，使盧綰、劉賈將卒二萬人，騎數百，渡白馬津入楚地，佐彭越燒楚積聚，復擊破楚軍燕郭西，攻下睢陽、外黃十七城。九月，羽謂海春侯大司馬曹咎曰：「謹守成皋。即漢王欲挑戰，慎勿與戰，勿令得東而已。我十五日必定梁地，復從將軍。」羽引兵東擊彭越。",
