      "readingAid": {
        "translation": "秋七月，天空中出現了彗星橫掃大角星宿（星孛於大角）。漢王劉邦接管了韓信的精銳大軍之後，漢軍軍威再次大振！八月，漢王率軍進駐黃河北岸面向南方，屯兵小修武，打算再次渡河同楚軍決戰。郎中鄭忠極力勸阻漢王，建議構築高壘深塹堅守不戰。漢王採納了鄭忠的良策，派遣盧綰、劉賈率領步兵兩萬人、騎兵數百人，強渡白馬津渡口深入西楚腹地，全力協助彭越焚燒摧毀楚軍的糧草物資積累，隨後在燕縣城郭以西大破楚軍部隊，接連攻克攻下了睢陽、外黃等十七座城池！九月，項羽後方糧道再次全面告急，項羽在東徵前特地嚴肅囑託海春侯、大司馬曹咎說：您務必謹慎死守成皋要塞！即使漢軍前來主動挑釁叫罵挑戰，您也千萬慎重絕對不要出城迎戰，只要不讓漢軍向東挺進一步就可以了！我項羽在十五天之內必定徹底平定梁地消滅彭越，隨後便班師折返同將軍會師！項羽隨即率領楚軍主力向東再次攻打彭越。",
        "analysis": "【篇旨與鄭忠止戰高壘深塹盧綰劉賈破楚十七城項羽命曹咎守成皋】漢軍貫徹持久消耗戰——鄭忠勸阻決戰構築高壘深塹，盧綰劉賈渡白馬津助彭越破十七城燒楚糧草；項羽再次被彭越調動東徵，臨行嚴令曹咎「謹守成皋慎勿與戰」。\\n【詞義訓詁】「星孛於大角」：古代彗星天象；「高壘深塹」：防禦戰略核心原則；「十五日必定梁地」：項羽對戰局時間表的過度樂觀估計。\\n【遊擊戰與正面防禦協同】彭越的敵後遊擊戰與劉賈的敵後穿插，徹底摧毀了項羽的後勤補給線，將西楚大軍拖入疲於奔命的泥潭。"
      }
