      "chapterId": "han-shu_ch-1",
      "order": 60,
      "canonicalText": "漢果數挑成皋戰，楚軍不出，使人辱之數日，大司馬咎怒，渡兵汜水。士卒半渡，漢擊之，大破楚軍，盡得楚國金玉貨賂。大司馬咎、長史欣皆自剄汜水上。漢王引兵渡河，復取成皋，軍廣武，就敖倉食。",
