      "id": "han-shu_ch-1_p-61",
      "chapterId": "han-shu_ch-1",
      "order": 61,
      "canonicalText": "羽下樑地十餘城，聞海春侯破，乃引兵還。漢軍方圍鍾離轔於滎陽東，聞羽至，盡走險阻。羽亦軍廣武，與漢相守數月。楚下兵罷，食絕；項羽數挑戰，漢王堅壁不出。羽乃為高俎，置太公其上，告漢王曰：「今不急下，吾亨太公。」漢王曰：「吾與羽俱北面受命懷王，約為兄弟，吾翁即若翁。必欲亨若翁，幸分我一杯羹。」羽怒，欲殺之。項伯曰：「天下事未可知。且為天下者不顧家，雖殺之無益，但益禍耳。」羽從之。項羽謂漢王曰：「天下洶洶數歲者，徒以吾兩人耳。願與漢王挑戰，決雌雄，毋徒罷天下之父子為也。」漢王笑謝曰：「吾寧鬥智，不能鬥力。」令壯士出挑戰。楚有善射者樓煩，漢挑戰三合，樓煩輒射殺之。漢王大怒，乃自臨軍。樓煩欲射，漢王瞋目譙之，樓煩目不敢視，手不敢發，遂走還走，不敢復出。羽聞之，自出。漢王與羽臨廣武澗交語，羽欲引漢王獨身挑戰。漢王數項羽十罪，羽大怒，伏弩射中漢王。漢王傷匈，乃捫足曰：「虜中吾指！」漢王病創臥，張良強請漢王起行勞軍，以安士卒，毋令楚乘勝。漢王行軍，疾甚，因馳入成皋。",
