        "analysis": "【篇旨與韓信請封假王張良陳平躡足封真齊王調兵夾擊】楚漢最高智謀瞬間——韓信請封假王引發劉邦暴怒，張良陳平「躡王足」化解政治危機，劉邦秒變臉「封真齊王」，化被動為主動成功調動韓信彭越大軍合圍項羽！\\n【詞義訓詁】「齊邊楚權輕」：韓信討封之政治藉口；「躡王足」：躡，音聶，暗中踩腳提醒；「大丈夫定諸侯即為真王何以假為」：劉邦神級危機公關轉化表演。\\n【帝王心術與政治成熟】在實力不對稱與大敵當前之際，剋制個人恩怨、以最高利益為重，慷慨讓渡封疆王位以換取戰略同盟合力滅楚。"
