      "id": "han-shu_ch-1_p-66",
      "chapterId": "han-shu_ch-1",
      "order": 66,
      "canonicalText": "五年冬十月，漢王追項羽至陽夏南止軍，與齊王信、魏相國越期會擊楚。至固陵，信、越期不至，楚擊漢軍，大破之。漢王復入壁，深塹而守。謂張良曰：「諸侯不從，奈何？」良對曰：「楚兵且破，未有分地，其不至固宜。君王能與共天下，可立致也。齊王信之立，非君王意，信亦自危；彭越本定梁地，始君王以魏豹故，拜越為相國。今豹死，越亦望王，而君王不早定。今能取睢陽以北至穀城皆以王彭越，從陳以東傅海與齊王信，信家在楚，其意亦欲得楚地。能出捐此地以許兩人，使各自為戰，楚易破也。」於是漢王發使使韓信、彭越。至，皆引兵來。",
