        "translation": "十一月，漢將劉賈率軍殺入西楚腹地，包圍了壽春重鎮。漢軍同時派遣祕密使者成功策反誘降了楚國最高軍事統帥大司馬周殷。大司馬周殷正式背叛項羽反叛楚國，率領舒縣部隊屠滅了六縣，調集九江全境軍隊主動迎接九江王黥布（英布），隨後兩軍合兵一路屠滅城父，跟隨劉賈的大軍一同奔赴垓下前線勝利會師！",
        "analysis": "【題解與背景】\\n本段選自《漢書》〈高帝紀〉第 67 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「十一月劉賈入楚地圍壽春漢亦遣人誘楚大司馬周殷……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「十」、「一」、「月」、「劉」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《漢書》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"
