      "chapterId": "han-shu_ch-1",
      "order": 68,
      "canonicalText": "十二月，圍羽垓下。羽夜聞漢軍四面皆楚歌，知盡得楚地，羽與數百騎走，潰圍南出。漢將灌嬰追斬羽東城。楚地皆降，獨魯不下。漢王引天下兵欲屠之，至其城下，聞絃歌之聲，為其守禮義，為主死節，乃持羽頭示其父老，魯乃降。以魯公禮葬羽穀城。",
