      "readingAid": {
        "translation": "十二月，漢軍統帥韓信指揮各路諸侯大軍六十萬人，將項羽殘軍十萬人重重包圍在垓下要塞（垓下之圍）。當天深夜，項羽在營帳中聽聞漢軍陣營四面八方全都高唱著淒涼的楚國鄉音民歌（四面楚歌），項羽大驚失色痛苦長嘆道：漢軍難道已經完全攻佔平定楚國全境了嗎？為什麼軍中楚人竟然有這麼多呢！項羽悲歌《垓下歌》之後，率領僅剩的八百名精銳騎兵連夜趁黑突圍，殺出重圍一路向南狂奔逃亡。漢軍騎兵統帥灌嬰率領五千鐵騎緊追不捨，在東城將項羽重重包圍，項羽拔劍在烏江自刎身亡，灌嬰部將斬下項羽首級！西楚全境各郡縣城池紛紛望風歸降，唯獨項羽當初受封為魯公的魯縣誓死堅守不肯投降。漢王劉邦率領天下大軍親臨魯縣準備下令屠城，抵達城牆之下時，卻遠遠聽見城中傳來陣陣絃歌誦讀禮樂之聲；漢王深感魯國百姓崇尚周公禮義、甘願為舊主守節赴死的崇高風骨，於是不忍屠城，命人手捧項羽首級展示給魯縣父老觀看，魯縣父老痛哭流涕這才正式開城歸降。漢王親自按照楚國魯公的諸侯最高國葬禮儀，將項羽隆重安葬在穀城，漢王親自為項羽哭臨安葬！",
        "analysis": "【篇旨與垓下之圍四面楚歌烏江自刎魯城絃歌魯公國葬】楚漢相爭終極史詩決戰——六十萬漢軍合圍垓下、張良四面楚歌瓦解楚軍士氣、項羽突圍自刎東城烏江；魯縣恪守禮義聞絃歌不降，劉邦持羽首降魯、以魯公之禮厚葬項羽，展現勝利者對英雄對手的最高敬意。\\n【詞義訓詁】「四面皆楚歌」：心理戰瓦解敵軍最後意志之千古典範；「聞絃歌之聲」：儒家禮樂文化在戰亂中的神聖堅守；「以魯公禮葬羽」：展現漢王安撫天下、收拾人心的宏大帝王政治胸懷。\\n【歷史大結局】西楚霸權正式終結，長達五年的楚漢戰爭以劉邦的徹底勝利而告終，中華歷史翻開漢帝國大一統的嶄新篇章。"
      }
