      "chapterId": "han-shu_ch-1",
      "order": 70,
      "canonicalText": "於是諸侯上疏曰：「楚王韓信、韓王信、淮南王英布、梁王彭越、故長沙王吳芮、趙王張敖、燕王臧荼，昧死再拜言皇帝陛下：大王起微細，誅暴逆，平定四海，有功者皆受分地為王、侯。大王不尊帝號，兩帝不行，明王不興。昧死上尊號。」漢王曰：「寡人聞帝者，賢者有也。虛言亡實，非所聞也。寡人何以堪之！」諸侯王皆曰：「大王發於蜀漢，定三秦，濟河，誅無道，聽天下，平定海內，功高德厚。帝號大王，宜也。」漢王凡三讓，遂即皇帝位於汜水之陽。尊王后曰皇后，太子曰皇太子。",
