      "canonicalText": "帝乃西都洛陽。夏五月，兵皆罷歸家。詔曰：「諸侯子在關中者，復之十二歲，其歸者半之。民前或相聚保山澤，不書名數。今天下已定，令各歸其縣，復故爵田宅，吏毋問其蚤暮。民以飢餓自賣為人奴婢者，皆免為庶人。軍吏卒免歸，各以爵次受田宅，及舊邑毋等級，免徭役。復大夫以上，至都尉皆免之。有功者以有司記，各受金帛田宅，有司無得擅加賦斂。」",
