      "readingAid": {
        "translation": "高祖皇帝隨後率軍向西進駐洛陽暫定為都城。夏五月，全國戰事結束，下令全體軍隊一律解甲休戰復員回家（兵皆罷歸家）。皇帝頒布復員善後詔書宣佈：凡是隨軍留在關中的諸侯子弟，免除其全家賦稅徭役整整十二年；返回原籍封國者免除六年。民間此前為了躲避戰亂成羣結隊逃入深山沼澤避難、未曾登記國家戶籍名冊的流民（不書名數），如今全天下已經徹底平定，命令他們各自返回原籍家鄉縣邑，全部恢復其原有的爵位、田地與住宅（復故爵田宅），官吏不得追究其登記遲早的罪責！民間百姓此前因極度饑荒為求一條活路把自己賣給豪強充當奴婢的（自賣為奴婢），一律全部無條件恢復為自由民庶人身份（免為庶人）！全體軍官士卒退役解甲歸田，各自依照其軍功爵位等級足額領取田地與住宅，在原籍村邑享受平等的戶籍待遇，終身免除徭役兵役；大夫爵位以上直至都尉全部享受免役特權。對在戰爭中立下戰功的將士，由主管官署造冊登記，各自頒發金銀布帛與田地房產，各級官吏嚴禁擅自向百姓私加任何苛捐雜稅！",
        "analysis": "【篇旨與解甲歸田免奴婢為庶人分田宅休養生息開國大憲章】漢初戰後經濟重建與社會復甦之最高綱領——軍隊大復員（兵皆罷歸家）、招撫流民重造戶籍、奴婢一律無條件釋放為平民、按軍功足額分給田宅、免除賦役，奠定「文景之治」休養生息之根本制度基石！\\n【詞義訓詁】「不書名數」：隱匿戶口未上戶籍者；「免為庶人」：世界人權史上罕見的全國性解放人身奴役法令；「以爵次受田宅」：二十等軍功爵位配給土地制度。\\n【經濟學與社會學重構】徹底終結秦末戰亂對人口勞動力的破壞，迅速恢復自耕農實體經濟，釋放勞動生產力，展現出極具歷史遠見的治國智慧。"
      }
