      "id": "han-shu_ch-1_p-73",
      "chapterId": "han-shu_ch-1",
      "order": 73,
      "canonicalText": "帝置酒雒陽南宮。上曰：「通侯諸將毋敢隱朕，皆言其情。吾所以有天下者何？項氏之所以失天下者何？」高起、王陵對曰：「陛下慢而侮人，項羽仁而愛人。然陛下使人攻城略地，所降下者因以予之，與天下同利也。項羽妬賢嫉能，有功者害之，賢者疑之，戰勝而不予人功，得地而不予人利，此所以失天下也。」上曰：「公知其一，未知其二。夫運籌帷幄之中，決勝千里之外，吾不如子房；鎮國家，撫百姓，給饋餉，不絕糧道，吾不如蕭何；連百萬之軍，戰必勝，攻必取，吾不如韓信。此三者，皆人傑也，吾能用之，此吾所以取天下也。項羽有一范增而不能用，此其所以為我擒也。」群臣說服。",
