      "readingAid": {
        "translation": "秋季七月，燕王臧荼發動叛亂，皇上親自率領軍隊前往討伐。九月，生擒了臧荼。皇上下詔要求諸侯王們，從有功之臣中挑選一人立為新的燕王。長沙王吳芮等人便上書請求立太尉長安侯盧綰為燕王。盧綰是豐邑人，與皇上是老同鄉且有舊交情。",
        "analysis": "【訓詁與名物】「將」在此作動詞，率領軍隊。「徵」通「徵」，討伐。「虜」指俘虜、生擒。「視有功者」指考察、挑選有功勞的人。「有舊」意指兩人過去有交情，盧綰與劉邦同鄉且同年同月同日生，關係極為親密。\\n【章法與結構】本段依循編年史的體例，按時間順序記載。首先簡述平定臧荼叛亂的過程（七月反，九月虜），節奏明快；接著敘述重新冊立燕王的政治過渡；最後以「綰，豐人，與上有舊」短短九字作結，為這場冊封背後的真正原因點睛，文字極度精鍊卻意味深長。\\n【思想與義理】這段記載生動地揭示了漢初政治分封的過渡性與帝王心術。劉邦名義上「詔諸侯王視有功者」來推舉燕王，看似大公無私，實則是透過群臣（長沙王吳芮等）之口，將自己最親信的同鄉盧綰推上王位。這反映了漢初為削弱異姓諸侯王勢力，逐步安排親信接管各方鎮守，是中央集權過程中極為巧妙的政治手腕與權力佈局。"
      }
