      "canonicalText": "上已封大功臣三十餘人，其餘爭功，未得行封。上居南宮，從復道上望見諸將往往數人耦語。上問張良：「此何語？」良曰：「陛下不知邪？此謀反耳。」上曰：「天下屬安定，何故反？」良曰：「陛下起布衣，與此屬取天下。今陛下已為天子，而所封皆蕭、曹故人，所誅皆生平仇怨。今軍吏計功，天下不足以遍封，此屬恐陛下不能盡封，又見疑過失及誅，故相聚謀反耳。」上曰：「為之奈何？」良曰：「上平生所憎，群臣所共知，誰最甚者？」上曰：「雍齒與我故，日者數嘗窘辱我。我欲殺之，為其功多，故不忍。」良曰：「今急先封雍齒以示群臣，群臣見雍齒封，則人人自堅矣。」上乃置酒，封雍齒為什方侯，而急趣丞相、御史定功行封。群臣罷酒，皆喜曰：「雍齒尚為侯，我屬無患矣！」",
