      "id": "han-shu_ch-1_p-84",
      "chapterId": "han-shu_ch-1",
      "order": 84,
      "canonicalText": "上歸櫟陽，五日一朝太公。太公家令說太公曰：「天亡二日，土亡二王。皇帝雖子，人主也；太公雖父，人臣也。奈何令人主拜人臣！如此，則威重不行。」後高祖朝，太公擁彗，迎門卻行。高祖大驚，下扶太公。太公曰：「帝，人主也，奈何以我亂天下法！」於是高祖乃尊太公為太上皇。心善家令言，賜金五百斤。",
