      "readingAid": {
        "translation": "高祖皇帝返回關中都城櫟陽，按照民間孝道每隔五天就親自前往府邸朝見探望父親太公一次。太公府中的管家家令私下勸導太公說：天空中絕不會有兩個太陽並存，大地上絕不會有兩位君王共治！皇帝雖然是您的親生兒子，但他乃是全天下的至尊君主（人主）；太公您雖然是皇帝的生身父親，但在國家法統上您依然是朝廷的臣民（人臣）。哪裡有讓天底下的最高君主反過來向臣民躬身下拜的道理呢！如果始終這樣做，皇帝的至尊威嚴與國家法度就無法在全天下樹立推行了！後來高祖再次前來府邸朝見時，太公手拿掃帚（擁彗），恭敬地在府門口迎接皇帝，面向皇帝步步倒退著行走（迎門卻行）以示人臣之禮。高祖見狀大驚失色，急忙快步跳下馬車親自上前攙扶父親。太公嚴肅說道：皇帝乃是全天下至尊的君主，怎能因為我一人而破壞顛倒了全天下的根本大法呢！高祖皇帝深感父子私情與國家法統兩難，於是正式下詔尊奉父親太公為太上皇！高祖內心深切讚賞家令的這番卓見，特地重重賞賜家令黃金五百斤！",
        "analysis": "【篇旨與太公家令進諫天無二日尊太公為太上皇父子私情與國家法統融通】中國禮法制度史重大創新——太公家令論「帝人主太公人臣」，太公擁彗卻行守法度，高祖尊父親為「太上皇」，以太上皇制度完美化解「忠孝不能兩全、天子無父」的憲政倫理困局！\\n【詞義訓詁】「天亡二日土亡二王」：國家主權之唯一性與排他性；「擁彗迎門卻行」：古代臣下迎接君王最謙卑之禮儀（拿著掃帚倒退走）；「太上皇」：尊崇父系血親至高尊榮同時免除其人臣朝拜義務之制度發明。\\n【憲政倫理考釋】太上皇制度成功融合了儒家孝道倫理與法家大一統君主集權體系，成為後世歷代王朝遵循的最高憲政典範。"
      }
