      "id": "han-shu_ch-1_p-86",
      "chapterId": "han-shu_ch-1",
      "order": 86,
      "canonicalText": "七年冬十月，上自將擊韓王信於銅鞮，斬其將。信亡走匈奴，與其將白土曼曼、王黃等立趙苗裔趙利為王，復收散兵，與匈奴共謀擊漢。上自晉陽往擊之，連破其軍，追至平城。匈奴冒頓單於縱精騎四十萬圍帝於白登，七日。漢軍中外不得相救餉。帝用陳平祕計，使使間厚遺閼氏。閼氏說單於曰：「兩主不相困。今得漢地，單於終非能居之也。且漢王亦有神，單於察之。」單於與韓王信將王黃、趙利期，而黃、利兵不來，疑其與漢有謀，乃開圍一角。會天大霧，漢軍皆持滿傅矢，面外，從白登直絕出。會天大霧，步卒皆銜枚，徐引去。遂與大軍合。",
