      "readingAid": {
        "translation": "漢七年冬十月，高祖皇帝親自率領三十二萬大軍征討韓王信，在銅鞮大破叛軍，陣斬其叛將。韓王信倉皇逃亡匈奴，同部將白土曼曼、王黃等人共同擁立趙國宗室趙利為趙王，重新收攏殘兵敗將，同匈奴冒頓單於合謀大舉進攻漢軍。高祖親自從晉陽率軍迎擊，連戰連捷接連擊破敵軍，乘勝一路追擊抵達平城。這時匈奴冒頓單於施展誘敵深入之計，突然集結四十萬控弦精銳騎兵，將高祖皇帝的先頭部隊團團包圍在白登山（白登之圍），整整包圍了七天七夜！漢軍內外斷絕，大軍主力無法前往救援送糧，軍中將士凍死凍傷者十有二三。高祖皇帝採納了陳平的絕密奇謀（陳平祕計），派遣祕密使者攜帶大量奇珍異寶、黃金美女畫像暗中重金賄賂冒頓單於的王后閼氏。閼氏受賄後在單於枕邊進言勸說道：兩國的最高君王不應當把彼此逼入你死我活的絕境。如今就算大王打下了漢朝的城池土地，我們匈奴人終究習慣了草原遊牧、根本無法適應在漢地定居啊！更何況漢王生來帶有神靈庇佑，希望單於深思明察！冒頓單於原本同韓王信的部將王黃、趙利約定在白登會師合擊，但王黃、趙利的援軍到了約定時間卻遲遲未到，單於心中暗自懷疑他們暗中同漢軍勾結有詐，於是在包圍圈的西南角悄悄網開一面打開了一道缺口！恰逢當天天空降下漫天大霧，漢軍將士全部搭滿強弓硬弩（持滿傅矢），箭頭全部一致朝向外側，由高祖親自率領從白登山這道缺口筆直突圍殺出！漢軍步兵將士口中全部含著木籤嚴禁出聲（銜枚），在大霧掩護下緩慢而有序地撤退離去，最終順利同趕來救援的漢軍主力大部隊成功會師！",
        "analysis": "【篇旨與白登之圍陳平六出奇計閼氏解圍漢軍持滿銜枚突圍】漢匈交鋒最驚險篇章——高祖輕敵冒進被冒頓單於四十萬精騎圍困白登山七日，陳平施絕密奇計厚賂閼氏解圍，漢軍持滿傅矢銜枚徐退，奠定漢初和親韜光養晦之國策基礎！\\n【詞義訓詁】「白登之圍」：漢代早期最大的軍事危機；「陳平祕計」：情報賄賂與後宮外交之絕殺奇謀；「持滿傅矢」：弓拉滿弦、箭搭弦上，保持高度戰鬥戒備；「銜枚」：口含木條防止出聲暴露。\\n【戰略大反思】白登之圍使劉邦清醒認識到漢初國力凋敝、騎兵落後於匈奴的殘酷現實，促使漢朝轉向和親休養、積蓄國力的戰略防禦階段。"
      }
