      "readingAid": {
        "translation": "漢七年春季，皇帝下令：凡是朝廷郎中官員犯罪應當判處剃去鬢鬚之刑（耐刑）以上刑罰的，主管官署必須先向皇帝正式奏請裁決後方可執行。民間百姓凡是家中生育新生兒嬰兒的，免除全家徭役賦稅整整兩年（復勿事二歲）。",
        "analysis": "【篇旨與郎中犯罪請讞保護優待官員生子免役鼓勵人口生育】漢初人口與司法大政——確立貴族官員法律特權程序（請讞制度萌芽），發布國家級生育補貼政策（生子免除兩年徭役），全力刺激戰後人口繁衍增長！\\n【詞義訓詁】「耐」：秦漢刑罰，剃去鬢鬚但保留頭髮之羞辱性輕刑；「請之」：請讞奏請皇帝親裁；「復勿事二歲」：免除兩年國家徭役兵役。\\n【人口政策里程碑】歷經秦末戰亂全國人口減半，漢高祖出臺生育免役政策，成為漢代人口快速復甦的核心制度保障。"
      }
