      "readingAid": {
        "translation": "二月，高祖皇帝抵達長安。丞相蕭何親自主持修築營建了巍峨宏偉的未央宮，拔地修築了高聳的東闕、北闕、宏偉的前殿、儲備兵器的武庫與儲存天下糧草的太倉。高祖皇帝看見未央宮宮殿如此壯麗雄偉奢華，大為惱怒，嚴肅斥責蕭何說：全天下動盪不安兵荒馬亂，全體將士百姓浴血奮戰勞苦了這麼多年，天下大業的成敗存亡尚不可知，你為什麼偏偏要將宮室修築得如此過度奢華豪橫！蕭何從容進諫回答說：正因為全天下尚未徹底平定，才可以趁此機會一鼓作氣建成這座天下第一宮室！況且堂堂天子以四海為家，宮殿如果不是無比巍峨壯麗就無法在全天下樹立至高無上的皇權威嚴（非壯麗無以重威），而且要修築得讓後世子孫再也無法在規模上有所超越！高祖皇帝聽後這才轉怒為喜豁然開朗。",
        "analysis": "【篇旨與蕭何營造未央宮非壯麗無以重威天子以四海為家】中國宮殿建築與皇權象徵哲學最高對話——蕭何營建未央宮（前殿、東闕、武庫、大倉），面對高祖斥責，以「天子以四海為家、非壯麗無以重威、無令後世有以加」確立大一統皇權建築之政治美學綱領！\\n【詞義訓詁】「未央宮」：取《詩經》「夜如何其夜未央」未盡長久之意；「東闕北闕」：天子宮門前之巍峨雙闕禮制建築；「非壯麗無以重威」：建築空間對民眾與諸侯之心理威懾效應；「無令後世有以加」：一步到位避免後世頻繁大興土木。\\n【政治建築學】未央宮不僅是皇帝居所，更是集國家統治中樞（前殿）、軍事指揮（武庫）、經濟命脈（大倉）於一體的超級國家堡壘。"
      }
