      "readingAid": {
        "translation": "漢八年冬，高祖皇帝親自率軍向東出征，在東垣圍剿討伐韓王信的殘餘叛軍。班師回朝途中再次路過趙國，趙國國相貫高、趙午等老臣對高祖此前百般侮辱輕慢趙王張敖深感奇恥大辱，於是祕密策劃密謀行刺暗殺高祖。高祖一行途經柏人縣，原本打算在柏人驛舍留宿過夜。高祖突然感到一陣心驚肉跳心神不寧（心動），詢問身邊侍從說：這座縣城叫什麼名字？侍從回答說：名叫柏人。高祖警惕地說：所謂柏人，這發音難道不正是意味著迫於人（被人所迫害脅迫）嗎！高祖當機立斷不在柏人過夜，立刻連夜策馬啟程離去！",
        "analysis": "【篇旨與高祖過趙貫高柏人謀刺心動避難】驚心動魄的行刺未遂案——趙相貫高因主受辱密謀在柏人驛舍行刺劉邦，劉邦憑藉非凡的直覺「心動」與語音敏感（柏人諧音迫於人）連夜離去化險為夷！\\n【詞義訓詁】「恥上不禮其王」：忠臣義士為維護君王尊嚴不惜弒君；「心動」：危機降臨前潛意識之強烈警覺；「柏人不迫於人乎」：巧妙利用地名讖緯直覺避禍。\\n【危機直覺與歷史偶然】劉邦高度敏銳的求生直覺再次在千鈞一發之際改變了歷史進程。"
      }
