        "analysis": "【篇旨與陣亡士卒槥車歸葬縣給衣衾少牢公祭撫恤制度】中國軍事撫卹史上最感人至深的國家安葬法令——陣亡將士遺骸由官府護送歸鄉，官給棺木壽衣，長吏親自主持少牢公祭，確立國家對烈士的崇高禮遇！\\n【詞義訓詁】「槥」：槥，音會，裝殮陣亡將士骸骨之靈柩；「祠以少牢」：羊豕二牲之高級國家祭祀；「長吏視葬」：地方行政一把手親自出席葬禮。\\n【軍隊政治工作典範】極大慰藉了烈士遺屬與三軍將士之心，使漢軍將士深感為國捐軀雖死猶榮，極大提升了軍隊凝聚力。"
