      "readingAid": {
        "translation": "十一月，皇帝下詔將齊國、楚國的原六國頂級貴族豪強大族——楚國的昭氏、屈氏、景氏、懷氏以及齊國的田氏五大宗族（五姓），全部強制遷徙至關中定居，朝廷給予他們最肥美富饒的田地與寬敞豪華的住宅（與利田宅）。",
        "analysis": "【篇旨與強制遷徙齊楚五大名門望族充實關中】強幹弱枝重大戰略舉措——將齊楚舊貴族核心（昭屈景懷田）連根拔起遷往關中，給予優厚田宅安撫，徹底瓦解關東反漢宗族基礎，充實京畿核心人口。\\n【詞義訓詁】「五姓」：先秦戰國最著名的五大頂級貴族宗族；「與利田宅」：以物質優待換取政治臣服。\\n【社會結構重構】徹底打破地方宗族對土地與基層社會的割據控制，將貴族勢力納入中央朝廷的直接監視之下。"
      }
