        "translation": "趙國國相貫高密謀在柏人刺殺高祖的陰謀敗露發覺，官府將貫高全夥逮捕歸案，並將趙王張敖一同逮捕下獄問罪。皇帝下達嚴厲詔令：凡是趙國大臣膽敢跟隨趙王進京的，一律株連誅滅三族！趙國郎中田叔、孟舒等十位忠義大臣毅然自己剃光頭髮、脖子上戴上鐵圈（自髠鉗），假扮成趙王的隨行家奴僕役，誓死追隨趙王進京護駕！在嚴酷的審訊大牢之中，貫高咬定牙關為趙王極力申冤，洗白證明趙王張敖對刺殺陰謀完全毫不知情。廷尉獄吏對貫高施行了極其殘酷的拷打杖責數千下，甚至用燒紅的鐵條燙刺皮肉（刺爇），全身上下被打得體無完膚沒有一塊好肉，貫高始終堅貞不屈不改供詞。高祖皇帝聽聞審訊實情後，由衷欽佩貫高敢作敢當誓死保全主君的俠義風骨，特赦了趙王張敖的死罪，廢除趙王爵位降封為宣平侯。",
        "analysis": "【篇旨與貫高柏人謀逆案發田叔自髠鉗護主貫高受刑不屈高祖義之赦趙王】漢初最震撼之政治大案——貫高受嚴刑拷打「刺爇身無可擊」至死力保趙王清白，田叔孟舒自髠鉗為奴從王，高祖義其風骨特赦趙王張敖為宣平侯。\\n【詞義訓詁】「自髠鉗」：髠，剃光頭髮；鉗，戴鐵頸圈；古代奴婢刑徒之標誌；「刺爇」：爇，音熱，火燒烙鐵酷刑；「義之」：敬佩其大義。\\n【法治與政治道德】貫高的剛烈與田叔的忠誠展現了古典俠士道義，劉邦順應民情法理免除趙王死罪，兼顧了皇權威嚴與道義人心。"
