      "readingAid": {
        "translation": "九月，代國相國陳豨在北方代地發動大規模武裝叛亂。高祖皇帝感慨說：陳豨當年曾經擔任過朕的使者，平生極其講求信用。代國邊防重地是朕最為焦慮關切的國防前線，所以朕當初才特別委以重任冊封陳豨統轄代地。陳豨如今竟然勾結王黃等人背叛朝廷謀反，禍害代地的廣大官吏百姓！朕決定親自統率大軍北上討伐他！",
        "analysis": "【題解與背景】\\n本段選自《漢書》〈高帝紀〉第 100 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\n【詞義與名物】\\n1. 經典名句解讀：引述「九月代相國陳豨反上曰豨嘗為吾使甚有信代地……」之章法語感與對偶語氣。\\n2. 訓詁與古漢語範式：本段重點解讀「九」、「月」、「代」等字詞之古代漢語語意、通假字與名物制度考釋。\\n【思想與史事脈絡】\\n深刻傳達《漢書》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：han-shu_ch-1_p-100）。"
      }
