      "id": "han-shu_ch-1_p-101",
      "chapterId": "han-shu_ch-1",
      "order": 101,
      "canonicalText": "十一年冬，上在邯鄲。豨將侯敞將萬餘人遊行，王黃將騎千餘軍曲逆，張春將卒萬餘人渡河擊聊城。漢將軍郭蒙與齊將擊，大破之。太尉勃給道定封龍，斬其將。上問邯鄲以南有收得大將者乎？得趙人周極，上厚賜之。",
