      "id": "han-shu_ch-1_p-111",
      "chapterId": "han-shu_ch-1",
      "order": 111,
      "canonicalText": "上還，過沛，留，置酒沛宮，悉召故人父老子弟佐酒。發沛中兒得百二十人，教之歌。酒酣，上擊築，自歌曰：「大風起兮雲飛揚，威加海內兮歸故鄉，安得猛士兮守四方！」令兒皆和習之。上乃起舞，忼慨傷懷，泣數行下。謂沛父兄曰：「遊子悲故鄉。吾雖都關中，萬歲之後吾魂魄猶思樂沛。且朕自沛公以誅暴逆，遂有天下，其以沛為朕湯沐邑，復其民，世世無有所與。」沛父老諸母故人日樂飲極歡，道舊故為笑樂。十餘日，上欲去，沛父兄固請。上曰：「吾人眾多，父兄不能給。」乃去。沛中空縣皆之邑西獻。上留止，張飲三日。沛父兄皆頓首曰：「沛幸得復，豐未得，唯陛下哀矜。」上曰：「豐者，吾所生長，極不忘耳。吾特以其為雍齒故反我為魏。」沛父兄固請之，乃並復豐，比沛。",
