      "canonicalText": "陳豨降將言豨反時燕王盧綰使人之豨所陰謀。上使闢陽侯審食其迎綰，綰稱疾。食其言綰反有端。春二月，使樊噲、周勃將兵擊綰。詔曰：「燕王綰與吾有故，愛之如子，聞與陳豨有謀，吾以為亡有，故使人迎綰。綰稱疾不來，謀反明矣。燕吏民非有罪也，賜其吏六百石以上爵各一級。與綰居，去來歸者，赦之，加爵亦一級。」詔諸侯王議可立為燕王者，長沙王臣等請立子建為燕王。",
