      "readingAid": {
        "translation": "陳豨軍中的投降將領向朝廷告發說：當初陳豨反叛之時，燕王盧綰曾祕密派遣特使前往陳豨軍營暗中聯絡串通。高祖派遣闢陽侯審食其前往燕國召見迎接盧綰進京，盧綰心懷恐懼託病推辭不肯奉詔。審食其回京報告說盧綰謀反已有確鑿端倪跡象。漢十二年春二月，皇帝派遣樊噲、周勃率軍北上征討盧綰。皇帝頒布詔書痛心感慨道：燕王盧綰與朕自幼是同鄉至交，朕愛護他如同自己的親生骨肉一樣；聽聞他同陳豨暗中勾結謀反，朕起初堅信絕無此事，所以纔派使者前往迎接他進京當面澄清。如今盧綰託病抗旨不肯進京，其謀反企圖已昭然若揭！然而燕國的廣大官吏百姓是毫無罪責的，特賜予燕國俸祿在六百石以上的各級官吏軍功爵位各一級；凡是此前跟隨盧綰叛亂、如今及時脫離叛軍迷途知返主動歸降大漢朝廷的人，朝廷一律全部赦免其罪責，並額外提升軍功爵位一級！皇帝下詔命天下諸侯王推選繼任燕王的人選，長沙王吳臣等人聯名請求冊立皇子劉建為燕王。",
        "analysis": "【篇旨與燕王盧綰涉叛高祖痛心派周勃擊燕赦燕吏民立皇子劉建】漢初最後一位同宗異姓王盧綰涉叛——高祖發出「愛之如子」之痛心浩嘆，派周勃討伐同時下詔赦免燕地官吏百姓，冊立皇子劉建為燕王。\\n【詞義訓詁】「與吾有故愛之如子」：劉邦對盧綰背叛最深沉的心理創傷；「非吏民之罪」：嚴格區分首惡與無辜百姓。\\n【同姓王體系全面確立】自此除南方偏遠長沙王吳芮外，全國所有異姓諸侯王全部被徹底清除，劉氏同姓王天下正式成型。"
      }
