      "canonicalText": "三月，詔曰：「吾立為天子，帝有天下，十二年於今矣。與天下之豪士賢大夫共定天下，同安輯之。其有功者上致之王，次為列侯，下乃食邑。而重臣之親，或為列侯，皆令自置吏，得賦斂，女子公主。為列侯食邑者，皆佩之印，賜大第室。吏二千石，徙之長安，受小第室。入蜀漢定三秦者，皆世世復。吾於天下賢士功臣，可謂亡負矣。其有不義背天子擅起兵者，與天下共伐誅之。佈告天下，使明知朕意。」",
