      "readingAid": {
        "translation": "三月，高祖皇帝頒布總結十二年帝王生涯之告天下功臣世爵憲章大詔宣佈：朕登基確立為天子，君臨統治全天下，自開國至今已經整整十二年了！朕同全天下的英雄豪傑與賢能大夫共同浴血奮戰平定天下，共同安撫治理萬民。凡是立下赫赫戰功的人，最高等級受封為諸侯王，次一等級受封為列侯，再次一等級受封食邑封地。而朝廷重臣的親屬，有的也破格封為列侯，全部允許他們在封國內自行設置官吏（自置吏），享有徵收封國田賦稅收的權力，其女兒受封為尊貴的公主。凡是身為列侯享有食邑封地的人，朝廷全部賜予象徵尊榮的金印紫綬，並在京師賜予宏偉豪華的大宅府邸（大第室）；凡是朝廷俸祿在二千石的高級官員，全部遷居京師長安，由朝廷統一分配標準住宅宅邸（小第室）；凡是當年跟隨朕一同進入巴蜀漢中、打回關中平定三秦的元老功臣，其家族世代享受免除一切賦稅徭役的崇高特權（世世復）！朕對待全天下的賢能之士與開國功臣，捫心自問可以說是無愧於心、絲毫沒有任何虧負辜負了啊（亡負矣）！今後如果再有居心不良大逆不道背叛天子、擅自私自起兵謀反作亂的人，全天下全體軍民將同朝廷一道共同討伐並將其徹底誅滅！特此頒布詔書公告全天下，讓全體臣民深刻明瞭朕的這番肺腑之意！",
        "analysis": "【篇旨與高祖十二年告天下功臣大詔吾於功臣可謂亡負剖符白馬之盟總綱】漢高祖臨終前最重要的政治總結與憲政盟約大詔——回顧十二年與豪士共定天下，詳述裂土封王、列侯封邑、賜大第室、世世免役之優厚體制，發出「吾於天下功臣可謂亡負」之千古浩嘆，確立「背天子擅起兵者天下共誅之」的鐵血政治規矩！\\n【詞義訓詁】「共定天下同安輯之」：共治天下之政治契約；「自置吏得賦斂」：列侯封國之自主行政與財稅權力；「亡負矣」：亡通無，無愧於心；「天下共伐誅之」：白馬之盟「非劉氏而王天下共擊之」之法律基石。\\n【政治憲章總結】系統總結了漢初軍功受益階層的權益保障機制，確立了中央集權與功臣集團長期共治的政治契約。"
      }
