      "canonicalText": "上擊布時，為流矢所中，行道疾。疾甚，呂後迎良醫。醫入見，上問醫。曰：「疾可治不醫曰可治。」於是上嫚罵之，曰：「吾以布衣提三尺取天下，此非天命乎？命乃在天，雖扁鵲何益！」遂不使治疾，賜黃金五十斤，罷之。呂後問曰：「陛下百歲後，蕭相國既死，誰令代之？」上曰：「曹參可。」問其次，曰：「",
