      "order": 123,
      "canonicalText": "呂後與審食其謀曰：「諸將故與帝為編戶民，北面為臣，心常鞅鞅，今乃事少主，非盡族是，天下不安。」以故不發喪。人或聞，以語酈商。酈商見審食其曰：「聞帝已崩，四日不發喪，欲誅諸將。誠如此，天下危矣。陳平、灌嬰將十萬守滎陽，樊噲、周勃將二十萬定燕代，此聞帝崩，諸將皆誅，必連兵還鄉，以攻關中。大臣內畔，諸將外反，亡可蹻足待也。」審食其入言之，乃以丁未發喪，大赦天下。",
