      "chapterId": "han-shu_ch-1",
      "order": 125,
      "canonicalText": "初，高祖不脩文學，而性明達，好謀，能聽，自監門戍卒，見之如舊。初順民心作三章之約。天下既定，命蕭何次律令，韓信申軍法，張蒼定章程，叔孫通制禮儀，陸賈造新語。又與功臣剖符作誓，丹書鐵契，金匱石室，藏之宗廟。雖日不暇給，規摹弘遠矣。",
