      "readingAid": {
        "translation": "當初，漢高祖平日裡雖然不拘泥於研讀儒家章句辭藻文學（不脩文學），然而他的天性極其開明通達（性明達），熱愛高明智謀，極其善於傾聽接納良策忠言（好謀能聽），上自王侯將相下至看守城門的小吏戍邊的普通士卒（監門戍卒），見到他們都能一見如故熱情相待如同多年老友。起兵之初順應全天下萬民民心制定了著名的約法三章；全天下徹底平定之後，高祖全面部署國家制度建設大政：命令丞相蕭何編纂制定大漢法典《九章律》（蕭何次律令）；命令大將軍韓信整頓申明國家軍事法典《軍法》（韓信申軍法）；命令歷法算術名臣張蒼修訂制定國家度量衡與財政章程（張蒼定章程）；命令儒學大師叔孫通制定朝廷君臣尊卑禮儀法度（叔孫通制禮儀）；命令大學士陸賈著述總結秦朝滅亡教訓的政論鉅著《新語》（陸賈造新語）。高祖又同全體開國功臣隆重舉行剖符盟誓大典，將盟誓文字用丹砂書寫在鐵券之上（丹書鐵契），鄭重鎖進黃金匱匣、珍藏在太廟石室之中（金匱石室），代代珍藏在宗廟祖廟之內。高祖皇帝在位十二年之中雖然日理萬機連一天閒暇時間都沒有（日不暇給），然而他為大漢帝國所奠定創立的國家各項制度規模，是何等的宏偉博大而深遠久遠啊（規摹弘遠矣）！",
        "analysis": "【篇旨與高祖品格總結制度奠基五大巨匠蕭何律令韓信軍法張蒼章程叔孫通禮儀陸賈新語丹書鐵券】班固對漢高祖治國功業最輝煌之歷史總結——「性明達好謀能聽見之如舊」、組織五大領域巨匠全面奠定漢家制度（蕭何九章律、韓信軍法、張蒼度量衡章程、叔孫通朝儀禮制、陸賈新語政治哲學），剖符盟誓丹書鐵券藏金匱石室，展現「規摹弘遠」之開國制度氣魄！\\n【詞義訓詁】「不脩文學性明達」：不尚空談虛文，具備穿透事物本質之政治大智慧；「監門戍卒見之如舊」：平民天子無與倫比的親和力與羣眾基礎；「蕭何次律令」：漢律體系奠基；「叔孫通制禮儀」：朝覲威嚴禮法重塑；「陸賈造新語」：漢代第一部儒法結合之治國哲學專著；「丹書鐵契金匱石室」：中國古代最高等級的國家政治盟約檔案。\\n【制度史巔峯評價】徹底打破「劉邦只會打仗不會治國」之偏見，展現漢高祖在法制、軍事、經濟、禮樂與意識形態五大維度全面構建漢家帝國大廈的宏偉政治格局。"
      }
