      "id": "han-shu_ch-1_p-126",
      "chapterId": "han-shu_ch-1",
      "order": 126,
      "canonicalText": "贊曰：春秋晉史蔡墨有言，陶唐氏既衰，其後有劉累，學擾龍，事孔甲，范氏其後也。而大夫範宣子亦曰：「祖自虞以上為陶唐氏，在夏為御龍氏，在商為豕韋氏，在周為唐杜氏，晉主夏盟為范氏。」范氏為晉士師，魯文公世奔秦。後歸於晉，其處者為劉氏。劉向雲戰國時劉氏自秦獲於魏。秦滅魏，遷大梁，都於豐，故周巿說雍齒曰「豐，故梁徙也」。是以頌高祖雲：「漢帝本系，出自唐帝。降及於周，在秦作劉。涉魏而東，遂為豐公。」豐公，蓋太上皇父。其遷日淺，墳墓在豐鮮焉。及高祖即位，置祠祀官，則有秦、晉、梁、荊之巫，世祠天地，綴之以祀，豈不信哉！由是推之，漢承堯運，德祚已盛，斷蛇著符，旗幟上赤，協於火德，自然之應，得天統矣。",
